# -*- coding: utf-8 -*-
"""
THE SILENT LANTERN - فانوس ساکت (PIXEL EDITION)
Landscape pixel-art horror adventure.  Mira, a lantern, and a bell that must never ring... except once.

* Real pixel art (320x180 canvas, scaled up with crisp pixels)
* Wide side-scrolling halls with a walkable FLOOR (move in 8 directions, not on a single line)
* Opening picture-story (comic) after START, and a short one at the end
* Level Fun (Backrooms): a top-down party maze of rooms and corridors, with tall yellow Partygoers, a party-order puzzle,
  closets under the tables to hide in - and if a Partygoer catches you, you die at once
* Controls (touch):  left side of screen = floating joystick,  ACT / LIGHT buttons on the right
* Controls (keyboard):  arrows/WASD move,  E/Enter/Space = ACT,  Q/F/Shift = LIGHT,  Esc = pause

Made for Pydroid 3 (pygame).  All art and sound are generated by code - no extra files needed.
"""
import os, sys, math, random, json, array, traceback, threading
import re as _re
import pygame

try:
    pygame.mixer.pre_init(22050, -16, 1, 512)
except Exception:
    pass
pygame.init()
pygame.display.set_caption('The Silent Lantern - فانوس ساکت')

W, H = 320, 180            # logical (pixel-art) resolution, always scaled up crisply
WALL_B = 108               # y where the back wall meets the floor
FY0, FY1 = 120, 172        # walkable floor band (feet y)
try:
    screen = pygame.display.set_mode((0, 0), pygame.FULLSCREEN)
except Exception:
    screen = pygame.display.set_mode((960, 540))
frame = pygame.Surface((W, H)).convert()
clock = pygame.time.Clock()

SPEED = 62.0
INK = (10, 10, 14); WHITE = (244, 246, 250); GOLD = (255, 206, 110); CYAN = (110, 226, 226)
RED = (226, 70, 90); PURP = (190, 140, 255); MINT = (150, 255, 225); GREYT = (196, 200, 208)

# ------------------------------------------------------------------ helpers
def clamp(v, a, b): return a if v < a else (b if v > b else v)
def mixc(a, b, t): return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))
def rect(s, c, x, y, w, h): pygame.draw.rect(s, c, (int(x), int(y), int(w), int(h)))
def poly(s, c, pts): pygame.draw.polygon(s, c, [(int(x), int(y)) for x, y in pts])
def sprite(w, h): return pygame.Surface((w, h), pygame.SRCALPHA)
def flip(s): return pygame.transform.flip(s, True, False)
def zoom(s, k): return pygame.transform.scale(s, (s.get_width() * k, s.get_height() * k))
def outline(img, col):
    w, h = img.get_size(); src = img.copy()
    def px(x, y): return 0 <= x < w and 0 <= y < h and src.get_at((x, y))[3] > 0
    for y in range(h):
        for x in range(w):
            if not px(x, y) and (px(x - 1, y) or px(x + 1, y) or px(x, y - 1) or px(x, y + 1)): img.set_at((x, y), col)
    return img
def finish(spr, col=(20, 22, 26)):
    out = sprite(spr.get_width() + 2, spr.get_height() + 2); out.blit(spr, (1, 1)); return outline(out, col)
def rows(g, data, x0, y0, pal):
    for j, row in enumerate(data):
        for i, ch in enumerate(row):
            c = pal.get(ch)
            if c: g.set_at((x0 + i, y0 + j), c)

