def translate(value):
    if LANGUAGE != 'fa' or not isinstance(value, str): return value
    if value.startswith('Name carved on the stone: '):
        nm, _s, rest = value[len('Name carved on the stone: '):].partition(', ')
        return 'نام حک‌شده روی سنگ: ' + NAMES_FA.get(nm, nm) + ('، ' + rest.translate(_PD) if rest else '')
    m_ = _re.match(r'^([A-Z]+), AGE (\d+)$', value)
    if m_: return NAMES_FA.get(m_.group(1), m_.group(1)) + '، ' + m_.group(2).translate(_PD) + ' ساله'
    if value.startswith('NAME RETURNED: '): nm = value.split(': ', 1)[1]; return 'نام بازگشت: ' + NAMES_FA.get(nm, nm)
    if value.startswith('YOU GOT: '): return 'گرفتی: ' + FA.get(value[9:], value[9:])
    if value.startswith('A FUSE SLOTS IN. '): return 'یه فیوز جا می‌شه. ' + value.split('. ',1)[1].replace(' OF ', ' از ').replace('.','')
    if value.startswith('DEPTH '): return 'عمق ' + value[6:]
    if value.startswith('VOLUME: '): return 'میزان صدا: ' + value.split(':', 1)[1].strip()
    if value.startswith('PARTY STEP '): return 'مرحله مهمانی ' + value[11:]
    if value.startswith('NAMES RETURNED '): return 'نام‌های بازگشته ' + value.split('NAMES RETURNED ', 1)[1]
    if value.startswith('IT CRACKS! ') and value.endswith(' MORE!'): return 'ترک برداشت! ' + value[len('IT CRACKS! '):-len(' MORE!')] + ' ضربه دیگر!'
