def _ar_shape(s):
    out = []; n = len(s); i = 0
    while i < n:
        ch = s[i]
        if ch == u'\u200c': i += 1; continue                               # half-space: only breaks the joining
        if ch not in _AR: out.append(ch); i += 1; continue
        pj = i > 0 and s[i - 1] in _AR and len(_AR[s[i - 1]]) == 4          # the letter before reaches forward into this one
        if ch == u'ل' and i + 1 < n and s[i + 1] in _LAM_ALEF:
            out.append(_LAM_ALEF[s[i + 1]][1 if pj else 0]); i += 2; continue
        f = _AR[ch]; nj = len(f) == 4 and i + 1 < n and s[i + 1] in _AR and s[i + 1] != u'ء'
        if len(f) == 1: out.append(f)
        elif len(f) == 2: out.append(f[1] if pj else f[0])
