HAIR = (96, 60, 42); HAIR_HI = (146, 98, 66); SKIN = (252, 222, 192); BLUSH = (240, 140, 140); EYE = (30, 24, 40); MOUTH = (190, 90, 90)
GREEN = (72, 172, 102); GREEN_DK = (40, 120, 72); GREEN_HI = (126, 214, 144); WHT = (250, 250, 250); WHT_SH = (200, 212, 218); SHOE = (120, 72, 52)

def build_girl(d, f):
    """Cute chibi girl: big head, brown bob, GREEN dress with WHITE collar and long WHITE sleeves.
       d = 'd' (front) | 'u' (back) | 'r' (right);  f = walk frame 0..3"""
    g = sprite(16, 24); oy = 1 if f in (1, 3) else 0
    pal = {'H': HAIR, 'h': HAIR_HI, 'S': SKIN, 'k': EYE, 'b': BLUSH, 'm': MOUTH}
    if d in ('d', 'u'):
        for x, lift in ((5, 1 if f == 1 else 0), (9, 1 if f == 3 else 0)):          # legs, white socks, brown shoes
            rect(g, SKIN, x, 19, 2, 2 - lift); rect(g, WHT, x, 21 - lift, 2, 1); rect(g, SHOE, x - 1, 22 - lift, 4, 1)
        rect(g, GREEN, 4, 15, 8, 2); rect(g, GREEN, 3, 17, 10, 1); rect(g, GREEN_DK, 3, 18, 10, 1); rect(g, GREEN_HI, 5, 15, 1, 2)
        rect(g, GREEN, 5, 12 + oy, 6, 4)                                                # torso
        rect(g, WHT, 5, 11 + oy, 6, 1)                                                  # collar
        if d == 'd': rect(g, WHT, 6, 12 + oy, 4, 1); rect(g, WHT, 7, 14 + oy, 2, 1)
        ay = -1 if f == 1 else (1 if f == 3 else 0)
        for x, a in ((3, ay), (11, -ay)):                                               # long white sleeves + hands
            rect(g, WHT, x, 12 + oy, 2, 3); rect(g, WHT_SH, x, 15 + oy, 2, 1); rect(g, SKIN, x, 16 + oy + a, 2, 1)
        if d == 'd':
            rows(g, ["..HHHHHH..", ".HHhhHHHH.", "HHHHHHHHHH", "HHSHHHHSHH", "HSSSSSSSSH",
                     "HSkSSSSkSH", "HSkSSSSkSH", "HSbSSSSbSH", "HHSSmmSSHH", "...SSSS..."], 3, 1 + oy, pal)
        else:
            rows(g, ["..HHHHHH..", ".HHhhHHHH.", "HHHHHHHHHH", "HHHHHHHHHH", "HHHHhHHHHH",
                     "HHHHHHHHHH", "HHHHHHHHHH", "HHHHHHHHHH", ".HHHHHHHH.", "...SSSS..."], 3, 1 + oy, pal)
            rect(g, WHT, 11, 4 + oy, 2, 2)                                               # white hair ribbon
    else:
        dd = (0, 1, 0, -1)[f]
        for x in (6 + dd, 8 - dd):
            rect(g, SKIN, x, 19, 2, 2); rect(g, WHT, x, 21, 2, 1); rect(g, SHOE, x, 22, 3, 1)
        rect(g, GREEN, 5, 15, 7, 2); rect(g, GREEN, 4, 17, 8, 1); rect(g, GREEN_DK, 4, 18, 8, 1)
        rect(g, GREEN, 6, 12 + oy, 5, 4); rect(g, WHT, 6, 11 + oy, 5, 1)
        rect(g, WHT, 7 + dd, 12 + oy, 2, 3); rect(g, WHT_SH, 7 + dd, 15 + oy, 2, 1); rect(g, SKIN, 7 + dd, 16 + oy, 2, 1)
        rows(g, ["..HHHHHH..", ".HHhhHHHH.", "HHHHHHHHHH", "HHHHHHHHSS", "HHHHHSSSSS",
                 "HHHHSSSkSS", "HHHHSSSkSS", "HHHHSbSSSS", "HHHHHSSmSS", "....SSSS.."], 3, 1 + oy, pal)
        rect(g, WHT, 2, 6 + oy, 2, 2)
    return finish(g)
