def glyph(g, kind, cx, cy, col):
    if kind == 'eye':
        poly(g, col, [(cx - 4, cy), (cx, cy - 3), (cx + 4, cy), (cx, cy + 3)]); rect(g, (10, 10, 20), cx - 1, cy - 1, 2, 2)
    elif kind == 'heart':
        pygame.draw.circle(g, col, (cx - 2, cy - 1), 2); pygame.draw.circle(g, col, (cx + 2, cy - 1), 2); poly(g, col, [(cx - 4, cy), (cx + 4, cy), (cx, cy + 4)])
    elif kind == 'tooth':
        poly(g, col, [(cx - 3, cy - 3), (cx + 3, cy - 3), (cx + 2, cy + 1), (cx + 1, cy + 4), (cx, cy + 1), (cx - 1, cy + 4), (cx - 2, cy + 1)])
    elif kind == 'crane':      # bird on one leg
        poly(g, col, [(cx - 4, cy + 1), (cx + 2, cy - 1), (cx + 4, cy + 1), (cx, cy + 3)])
        pygame.draw.line(g, col, (cx + 2, cy - 1), (cx + 3, cy - 5), 1); rect(g, col, cx + 3, cy - 6, 2, 2); rect(g, col, cx + 5, cy - 5, 2, 1)
        pygame.draw.line(g, col, (cx - 1, cy + 3), (cx - 1, cy + 6), 1); pygame.draw.line(g, col, (cx - 4, cy + 1), (cx - 6, cy - 1), 1)
    elif kind == 'fox':        # pointy ears, narrow muzzle
        poly(g, col, [(cx - 5, cy - 6), (cx - 1, cy - 2), (cx - 5, cy - 1)]); poly(g, col, [(cx + 5, cy - 6), (cx + 1, cy - 2), (cx + 5, cy - 1)])
        poly(g, col, [(cx - 4, cy - 2), (cx + 4, cy - 2), (cx + 3, cy + 1), (cx, cy + 5), (cx - 3, cy + 1)]); rect(g, (20, 14, 14), cx - 1, cy + 4, 2, 1)
    elif kind == 'deer':       # head with branching antlers
        poly(g, col, [(cx - 2, cy - 1), (cx + 2, cy - 1), (cx + 1, cy + 5), (cx - 1, cy + 5)])
        for sg in (-1, 1):
            pygame.draw.line(g, col, (cx + sg * 2, cy - 1), (cx + sg * 4, cy - 5), 1); pygame.draw.line(g, col, (cx + sg * 4, cy - 5), (cx + sg * 6, cy - 7), 1)
            pygame.draw.line(g, col, (cx + sg * 3, cy - 3), (cx + sg * 6, cy - 3), 1)
    elif kind == 'owl':        # round body, two big eyes
        pygame.draw.circle(g, col, (cx, cy + 1), 5); poly(g, col, [(cx - 5, cy - 3), (cx - 3, cy - 6), (cx - 1, cy - 3)]); poly(g, col, [(cx + 5, cy - 3), (cx + 3, cy - 6), (cx + 1, cy - 3)])
        for sx in (-2, 2): pygame.draw.circle(g, (20, 14, 14), (cx + sx, cy), 2); rect(g, WHITE, cx + sx, cy - 1, 1, 1)
        rect(g, (230, 160, 60), cx, cy + 2, 1, 2)
