def build_dean(f):
    g = sprite(30, 46); BN = (222, 214, 196); BS = (170, 160, 144); RB = (74, 12, 28); RD = (38, 6, 18); GD = (232, 176, 80); IK = (6, 2, 8); BL = (214, 36, 56); K = (8, 4, 12)
    poly(g, RB, [(9, 17), (21, 17), (27, 45), (3, 45)]); poly(g, RD, [(15, 18), (21, 17), (27, 45), (16, 45)])
    for i in range(6): x = 3 + i * 4; poly(g, K, [(x, 45), (x + 4, 45), (x + 2, 42 - ((i + f) % 2) * 2)])      # torn hem
    rect(g, GD, 14, 19, 2, 20)
    ay = f * 2                                                                                                   # arms far too long, spindly fingers
    for sx, tx in ((8, 2), (22, 28)):
        sg = 1 if sx < 15 else -1
        pygame.draw.line(g, BN, (sx, 19), (tx, 32 + ay), 1); pygame.draw.line(g, BN, (tx, 32 + ay), (tx + sg, 43 + ay), 1)
        for dx in (-1, 0, 1): pygame.draw.line(g, BN, (tx + sg, 43 + ay), (tx + sg + dx, 45), 1)
    pygame.draw.line(g, BS, (11, 24), (7, 31 - f), 1); pygame.draw.line(g, BS, (19, 24), (23, 31 - f), 1)      # a second, thinner pair of arms
    pygame.draw.ellipse(g, BN, (9, 1, 12, 18))                                                                   # long pale face
    for ey in (4, 8, 12):                                                                                        # six eyes
        for ex in (12, 17): rect(g, IK, ex, ey, 2, 2); rect(g, BL, ex + f, ey, 1, 1)
    rect(g, IK, 8, 15, 15, 3)                                                                                    # a grin wider than the face
    for x in range(9, 22, 2): rect(g, BN, x, 15, 1, 2)
    for x in (10, 13, 16, 19): poly(g, GD, [(x, 3), (x + 2, 3), (x + 1, 0)])                                    # crown of thorns
    glyph(g, 'eye', 15, 29, BL)
    return finish(g, (120, 40, 60))
