def build_partygoer(kind, f, mad):
    g = sprite(26, 48); DK = (26, 16, 8); MW = (250, 244, 226); Y = (232, 198, 30); YD = (164, 126, 12); YL = (252, 232, 110); a = 1 if f else -1; q = 1 if f else 0
    rect(g, YD, 9, 34, 3, 13 - q); rect(g, YD, 14, 34, 3, 12 + q); rect(g, DK, 8, 46 - q, 5, 2); rect(g, DK, 13, 45 + q, 5, 2)          # thin bent legs
    poly(g, Y, [(8, 23), (18, 21), (17, 35), (10, 35)]); poly(g, YD, [(8, 23), (10, 22), (12, 35), (10, 35)])                              # hunched, leaning torso
    for yy in (26, 29, 32): pygame.draw.line(g, YD, (11, yy), (16, yy - 1), 1)                                                          # ribs
    pygame.draw.line(g, YD, (7, 24), (3, 35 + a), 2); pygame.draw.line(g, YD, (3, 35 + a), (4, 45 + a), 2)                               # left arm: reaches the floor
    pygame.draw.line(g, YD, (19, 22), (23, 34 - a), 2); pygame.draw.line(g, YD, (23, 34 - a), (21, 46 - a), 2)                           # right arm: even longer
    for dx in (-2, 0, 2):
        pygame.draw.line(g, MW, (4, 45 + a), (4 + dx, 47 + a), 1); pygame.draw.line(g, MW, (21, 46 - a), (21 + dx, 47), 1)               # claws
    pygame.draw.line(g, YD, (13, 23), (15, 17), 3)                                                                                      # bent neck
    pygame.draw.ellipse(g, Y, (8, 2, 16, 19)); rect(g, YL, 11, 4, 4, 1); pygame.draw.line(g, YD, (9, 11), (10, 15), 1)                   # crooked long head
    pygame.draw.ellipse(g, DK, (10, 8, 5, 6)); pygame.draw.ellipse(g, DK, (18, 10, 4, 5))                                                # uneven hollow eyes
    if mad:
        rect(g, RED, 11, 10, 2, 2); rect(g, RED, 19, 11, 2, 2); pygame.draw.line(g, DK, (9, 6), (14, 9), 1); pygame.draw.line(g, DK, (23, 8), (19, 10), 1)
        poly(g, (70, 8, 26), [(9, 15), (23, 17), (22, 21), (11, 20)])
        for x in range(10, 22, 2): rect(g, MW, x, 15 + (x - 9) // 6, 1, 2)
        for x in range(11, 21, 2): rect(g, MW, x, 19, 1, 1)
    else:
        rect(g, WHITE, 11, 9, 1, 1); rect(g, WHITE, 19, 11, 1, 1)
        poly(g, DK, [(9, 15), (23, 17), (22, 19), (10, 18)])                                                                              # a far too wide, lopsided grin
        for x in range(11, 22, 2): rect(g, MW, x, 16 + (x - 9) // 6, 1, 1)
    return finish(g, (80, 52, 0))
