        rect(g, P['hairh'], x0 + 3, y0 + 1, 3, 1); rect(g, P['hairh'], x0 + 2, y0 + 2, 2, 1); rect(g, P_SK, x0 + 2, y0 + 3, 1, 1); rect(g, P_SK, x0 + 7, y0 + 3, 1, 1)
