        rect(g, P['shoe'], 8 - sw, 32, 5, 2); rect(g, P['shoe'], 8 + sw, 32, 5, 2); rect(g, (74, 62, 64), 10 + sw, 32, 2, 1)
        rect(g, P['top'], 6, 13 + oy, 8, 10); rect(g, P['toph'], 7, 14 + oy, 1, 8); rect(g, P['tops'], 13, 14 + oy, 1, 8); rect(g, tr, 9, 13 + oy, 4, 1); rect(g, P['belt'], 6, 22 + oy, 8, 2); rect(g, P['buck'], 12, 22 + oy, 1, 2)
