PERSON = {}
for _k in (0, 1):
    for _v, _p in (('f', 'idle'), ('f', 'shout'), ('f', 'hips'), ('s', 'idle'), ('s', 'point'), ('s', 'shout')): PERSON[(_k, _v, _p, 0)] = build_person2(_k, _v, _p, 0)
    for _f in range(4): PERSON[(_k, 's', 'walk', _f)] = build_person2(_k, 's', 'walk', _f)
PERSON_FLIP = dict((k_, flip(v_)) for k_, v_ in PERSON.items() if k_[1] == 's')                  # side views face right; these face left
_ARGUE = ((.7, 's', 'idle'), (.5, 's', 'point'), (.4, 's', 'shout'), (.4, 's', 'point'), (.4, 's', 'shout'), (.6, 'f', 'shout'), (.5, 's', 'idle'), (.6, 'f', 'hips'), (.4, 's', 'point'), (.5, 's', 'shout'))
_ARGUE_T = sum(a_[0] for a_ in _ARGUE)
def person_img(kind, t, face=1, ph=0.0, mode='argue'):                          # -> (picture, vertical bob).  mode: 'argue' (shouting), 'still' (standing calmly), 'walk'
    if mode == 'walk': k = (kind, 's', 'walk', int(t * 8) % 4); bob = 0
    elif mode == 'still': k = (kind, 's', 'idle', 0); bob = 0
    else:
        u = (t + ph) % _ARGUE_T; v = 's'; p = 'idle'
        for d, v, p in _ARGUE:
            if u < d: break
            u -= d
        k = (kind, v, p, 0); bob = -1 if (p in ('shout', 'point') and int(t * 9) % 2) else 0
    return (PERSON_FLIP[k] if (face < 0 and k[1] == 's') else PERSON[k]), bob
