_vig = []
def vignette():
    if _vig: return _vig[0]
    g = pygame.Surface((W, H)); g.fill((255, 255, 255))
    for i in range(24):
        v = int(255 * (1 - .8 * (1 - i / 24.0))); pygame.draw.rect(g, (v, v, v), (i, i, W - 2 * i, H - 2 * i), 1)
    _vig.append(g); return g
def glitch(surf, n=3, mx=8):
    for _ in range(n):
        y = random.randint(0, H - 14); h = random.randint(3, 12); dx = random.randint(-mx, mx)
        strip = pygame.Surface((W, h)); strip.blit(surf, (0, 0), (0, y, W, h)); surf.blit(strip, (dx, y))

def build_pillar(seed, wood=False):
    rng = random.Random(seed); g = sprite(44, 176)
    if wood:
        rect(g, (34, 20, 16), 4, 0, 36, 168); rect(g, (104, 66, 46), 4, 0, 2, 168); rect(g, (160, 108, 74), 39, 0, 1, 168)
        for x in range(10, 40, 6): pygame.draw.line(g, (22, 12, 10), (x + rng.randint(-1, 1), 0), (x + rng.randint(-2, 2), 166), 1)
        rect(g, (20, 12, 10), 0, 166, 44, 10); rect(g, (96, 64, 46), 0, 166, 44, 1)
        for y in (30, 110): rect(g, (76, 44, 34), 3, y, 38, 4)
        for _ in range(3):
            x = rng.randint(10, 30); y = rng.randint(20, 120); rect(g, (226, 220, 198), x, y, 4, 11); rect(g, (170, 40, 40), x + 1, y + 2, 2, 1); rect(g, (170, 40, 40), x + 1, y + 6, 2, 3)
        return g
    rect(g, (12, 12, 16), 4, 0, 36, 168); rect(g, (44, 44, 52), 4, 0, 2, 168); rect(g, (86, 86, 98), 39, 0, 1, 168)
    rect(g, (22, 22, 28), 0, 166, 44, 10); rect(g, (60, 60, 70), 0, 166, 44, 1)
    for _ in range(4):
        x = rng.randint(12, 32); y = rng.randint(10, 80); pts = [(x, y)]
        for k in range(5): x += rng.randint(-4, 4); y += rng.randint(8, 18); pts.append((clamp(x, 6, 38), y))
        pygame.draw.lines(g, (74, 74, 86), False, pts, 1)
    for _ in range(6): rect(g, (6, 6, 8), rng.randint(5, 36), rng.randint(0, 160), rng.randint(2, 5), rng.randint(2, 4))
    return g

# ------------------------------------------------------------------ lighting (multiplied mask: ambient + additive lights)
_ls = {}
def light(r, tint=(255, 255, 255)):
    k = (r, tint)
    if k not in _ls:
        s = pygame.Surface((r * 2, r * 2)); s.fill((0, 0, 0)); n = 6
        for i in range(n):
            v = int(255 * ((i + 1) / float(n)) ** 1.2); pygame.draw.circle(s, (v, v, v), (r, r), max(1, int(r * (n - i) / float(n))))
        s.fill(tint, special_flags=pygame.BLEND_RGB_MULT); _ls[k] = s
    return _ls[k]
mask = pygame.Surface((W, H))
def apply_light(ambient, lights):
    mask.fill(ambient)
    for x, y, r, tint in lights:
        if -r < x < W + r: mask.blit(light(r, tint), (int(x) - r, int(y) - r), special_flags=pygame.BLEND_RGB_ADD)
    frame.blit(mask, (0, 0), special_flags=pygame.BLEND_RGB_MULT)

# ------------------------------------------------------------------ audio (generated, built in a background thread)
SFX = {}; MUSIC = {}
def _tone(rate, f0, f1, dur, vol=.35, wave='sine', decay=2.0):
    n = max(1, int(rate * dur)); out = []; ph = 0.0
    for i in range(n):
        k = i / float(n); ph += 2 * math.pi * (f0 + (f1 - f0) * k) / rate
        if wave == 'sine': v = math.sin(ph)
        elif wave == 'square': v = .6 if math.sin(ph) > 0 else -.6
        elif wave == 'saw': v = ((ph / (2 * math.pi)) % 1.0) * 2 - 1
        else: v = random.uniform(-1, 1)
        env = (1 - k) ** decay
        if k < .02: env *= k / .02
        out.append(v * vol * env)
    return out
def _mix(*tr):
    n = max(len(t) for t in tr); out = [0.0] * n
    for t in tr:
        for i, v in enumerate(t): out[i] += v
    return out
def _cat(*tr):
    out = []
    for t in tr: out += t
    return out
def _sound(samples, ch):
    data = array.array('h', [int(clamp(s, -1, 1) * 30000) for s in samples])
    if ch == 2:
        d2 = array.array('h')
        for v in data: d2.append(v); d2.append(v)
        data = d2
    return pygame.mixer.Sound(buffer=data.tobytes())
def build_audio():
    try:
        if not pygame.mixer.get_init(): pygame.mixer.init(22050, -16, 1, 512)
        init = pygame.mixer.get_init()
        if not init or init[1] != -16: return
        R, ch = init[0], init[2]; T = lambda *a, **k: _tone(R, *a, **k)
        rec = {'blip': T(700, 700, .02, .08, 'square', 1), 'blip_m': T(900, 960, .03, .09, 'square', 1), 'blip_v': T(0, 0, .035, .07, 'noise', 2),
               'blip_c': T(100, 68, .08, .2, 'saw', 1), 'blip_a': T(520, 820, .06, .09, 'sine', 1), 'hurt': _mix(T(240, 70, .3, .4, 'saw', 1), T(0, 0, .12, .25, 'noise', 2)),
               'pulse': _mix(T(300, 1000, .5, .3, 'sine', 1.2), T(450, 1500, .5, .14, 'sine', 1.2)), 'kill': T(520, 90, .25, .3, 'square', 1.5),
               'wrong': T(150, 90, .32, .35, 'saw', 1), 'rune0': T(440, 440, .4, .3, 'sine', 2), 'rune1': T(554, 554, .4, .3, 'sine', 2), 'rune2': T(659, 659, .5, .3, 'sine', 2),
               'lamp': T(660, 1320, .2, .25, 'sine', 2), 'open': _cat(*[T(f, f, .1, .3, 'sine', 1.2) for f in (392, 523, 659, 784, 1047)]),
               'step': T(0, 0, .03, .05, 'noise', 3), 'thump': _cat(T(60, 40, .12, .5, 'sine', 1.5), [0.0] * int(R * .12), T(55, 38, .14, .4, 'sine', 1.5)),
               'creak': _mix(T(120, 250, .5, .1, 'saw', .8), T(123, 258, .5, .08, 'saw', .8)),
               'scare': _mix(T(62, 30, 1.0, .55, 'saw', 1.2), T(0, 0, .6, .45, 'noise', 1.6), T(1200, 150, .5, .25, 'square', 2.5)),
               'glitch': _cat(T(0, 0, .06, .5, 'noise', 1), [0.0] * int(R * .03), T(300, 60, .1, .4, 'square', 1)),
               'whisper': T(0, 0, .7, .13, 'noise', .8), 'buzz': _mix(T(120, 120, .5, .12, 'saw', .3), T(240, 240, .5, .05, 'sine', .3))}
        rec['pop'] = _mix(T(0, 0, .06, .5, 'noise', 3), T(900, 200, .06, .25, 'sine', 2))
        rec['horn'] = _mix(T(380, 520, .38, .22, 'square', .6), T(385, 530, .38, .12, 'saw', .6))
        rec['mbox'] = _cat(*[_mix(T(f, f, .3, .14, 'sine', 2.0), T(f * 1.012, f * 1.012, .3, .1, 'sine', 2.0), T(f * 2, f * 2, .2, .04, 'sine', 3.0)) for f in (523, 659, 784, 659, 587, 698, 880, 698, 523, 392)])
        for name, s in rec.items(): SFX[name] = _sound(s, ch)
        base = 196.0
        SFX['bell'] = _sound(_mix(*[T(base * m, base * m, 3.0, v, 'sine', 1.6) for m, v in ((1, .3), (2, .2), (2.76, .12), (5.4, .06))]), ch)
        n = R * 12; buf = [0.0] * n
        for f, v in ((55.0, .10), (82.5, .06)):
            for i in range(n): buf[i] += math.sin(2 * math.pi * f * i / R) * v * (0.6 + 0.4 * math.sin(2 * math.pi * i / n * 2))
        for t0, f in ((0.4, 440), (2.3, 330), (4.0, 392), (5.4, 262), (7.5, 330), (9.1, 392), (10.4, 294)):
            note = _mix(T(f, f, 1.6, .09, 'sine', 2.2), T(f * 2, f * 2, 1.2, .03, 'sine', 2.5)); s0 = int(t0 * R)
            for i, v in enumerate(note): buf[(s0 + i) % n] += v
        MUSIC['snd'] = _sound(buf, ch)
    except Exception:
        pass

