def is_wood(R): return bool(R.get('village') or THEMES[R['theme']].get('wood'))

def draw_window(s, cx, T, rng, col=None):                       # gothic (stone rooms)
    ww, top, bot = 40, 22, 92; spring = top + 26; col = col or T['glass']
    pts = [(cx - ww // 2, bot), (cx - ww // 2, spring), (cx, top), (cx + ww // 2, spring), (cx + ww // 2, bot)]
    pygame.draw.polygon(s, col, pts); pygame.draw.polygon(s, T['col'], pts, 2)
    pygame.draw.line(s, T['col'], (cx, top + 4), (cx, bot), 1); pygame.draw.line(s, T['col'], (cx - ww // 2, spring + 12), (cx + ww // 2, spring + 12), 1)
    for _ in range(3):
        x = cx + rng.randint(-14, 14); y = rng.randint(top + 14, bot - 22); p2 = [(x, y)]
        for k in range(3): x += rng.randint(-6, 6); y += rng.randint(4, 10); p2.append((x, y))
        pygame.draw.lines(s, T['col'], False, p2, 1)
    rect(s, T['cap'], cx - ww // 2 - 3, bot, ww + 6, 4); rect(s, T['col'], cx - ww // 2 - 3, bot + 4, ww + 6, 1)
def draw_shoji(s, cx, T, rng, col=None):                         # wooden lattice window with torn paper
    x0, top, bot = cx - 17, 26, 90; col = col or T['glass']; dk = T['col']
    rect(s, dk, x0 - 3, top - 3, 40, bot - top + 6); rect(s, col, x0, top, 34, bot - top)
    for gx in (x0 + 11, x0 + 22): pygame.draw.line(s, dk, (gx, top), (gx, bot), 1)
    for gy in range(top + 11, bot, 11): pygame.draw.line(s, dk, (x0, gy), (x0 + 33, gy), 1)
    for _ in range(3): rect(s, mixc(col, (0, 0, 0), .55), x0 + rng.randint(1, 26), top + rng.randint(2, 50), rng.randint(3, 6), rng.randint(4, 9))
    rect(s, T['cap'], x0 - 6, top - 7, 46, 4); rect(s, T['cap'], x0 - 5, bot + 3, 44, 3)
