def draw_decor(s, R, T, rng):
    for kind, x in R.get('decor', []):
        if kind == 'altar':
            rect(s, (70, 44, 32), x - 40, WALL_B - 26, 80, 22); rect(s, (118, 82, 56), x - 44, WALL_B - 30, 88, 5); rect(s, (40, 24, 20), x - 34, WALL_B - 22, 68, 2)
            rect(s, (50, 30, 24), x - 26, 32, 5, WALL_B - 62); rect(s, (50, 30, 24), x + 21, 32, 5, WALL_B - 62); rect(s, (50, 30, 24), x - 29, 29, 62, 5)
            rect(s, mixc(T['wall'], (255, 255, 255), .12), x - 20, 36, 40, 34)       # pale square: where the bell hung
            pygame.draw.line(s, (190, 170, 130), (x, 35), (x, 70), 2); rect(s, (190, 60, 50), x - 2, 70, 5, 6)
            for dx in (-30, -18, 18, 30): rect(s, (226, 220, 206), x + dx, WALL_B - 36, 2, 6)
        elif kind == 'lantern':
            pygame.draw.line(s, (40, 28, 24), (x, 12), (x, 32), 1); pygame.draw.ellipse(s, (150, 56, 48), (x - 6, 32, 12, 15)); pygame.draw.ellipse(s, (96, 34, 30), (x - 6, 32, 12, 15), 1)
            pygame.draw.line(s, (96, 34, 30), (x - 6, 40), (x + 5, 40), 1); rect(s, (40, 28, 24), x - 3, 31, 6, 2); rect(s, (40, 28, 24), x - 1, 47, 2, 5)
        elif kind == 'shelf':
            for sy in (50, 72):
                rect(s, (60, 40, 30), x - 26, sy, 52, 3)
                for i in range(7): rect(s, mixc((120, 90, 70), (60, 80, 110), rng.random()), x - 24 + i * 7, sy - rng.randint(6, 12), 5, 12)
        elif kind == 'table':
            rect(s, (98, 68, 46), x - 24, WALL_B - 24, 48, 4); rect(s, (60, 40, 30), x - 22, WALL_B - 20, 3, 18); rect(s, (60, 40, 30), x + 19, WALL_B - 20, 3, 18)
            for dx in (-14, -2, 12): rect(s, (206, 200, 186), x + dx, WALL_B - 28, 4, 4)
        elif kind == 'stove':
            rect(s, (60, 56, 60), x - 3, 20, 6, WALL_B - 60); rect(s, (44, 40, 44), x - 14, WALL_B - 38, 28, 36); rect(s, (70, 66, 70), x - 16, WALL_B - 40, 32, 3)
            rect(s, (232, 110, 50), x - 8, WALL_B - 22, 16, 12); rect(s, (255, 206, 110), x - 5, WALL_B - 18, 10, 8)
        elif kind == 'map':
            rect(s, (200, 180, 120), x - 22, 30, 44, 34); rect(s, (30, 40, 86), x - 20, 32, 40, 30)
            for _ in range(14): s.set_at((x - 18 + rng.randint(0, 36), 34 + rng.randint(0, 26)), (240, 240, 255))
            pygame.draw.line(s, (255, 214, 120), (x - 16, 36), (x + 14, 58), 1)
        elif kind == 'sign':
            rect(s, (70, 52, 40), x - 2, 62, 4, 46); rect(s, (118, 90, 64), x - 22, 48, 44, 18); rect(s, (60, 44, 34), x - 22, 48, 44, 2)
            for yy in (53, 57, 61): rect(s, (60, 44, 34), x - 16, yy, 32 - (yy - 53), 1)
        elif kind == 'well':
            rect(s, (110, 118, 134), x - 16, WALL_B - 14, 32, 14); rect(s, (224, 234, 246), x - 17, WALL_B - 16, 34, 3)
            rect(s, (60, 48, 52), x - 14, WALL_B - 42, 3, 28); rect(s, (60, 48, 52), x + 11, WALL_B - 42, 3, 28)
            poly(s, (60, 48, 52), [(x - 21, WALL_B - 40), (x, WALL_B - 54), (x + 21, WALL_B - 40)]); poly(s, (224, 234, 246), [(x - 21, WALL_B - 40), (x, WALL_B - 54), (x, WALL_B - 51), (x - 17, WALL_B - 40)])
        elif kind == 'nest':                                          # doorways inside doorways inside doorways
            for lvl in range(5):
                ww = int(32 * (.7 ** lvl)); hh = int(64 * (.7 ** lvl)); rect(s, mixc((116, 94, 42), (24, 18, 8), lvl / 4.0), x - ww // 2, WALL_B - 4 - hh, ww, hh)
                if lvl == 0: rect(s, (190, 166, 80), x - ww // 2 - 2, WALL_B - 4 - hh - 2, ww + 4, 2)
        elif kind == 'lectern':
            rect(s, (40, 22, 26), x - 14, WALL_B - 30, 28, 30); rect(s, (74, 42, 46), x - 17, WALL_B - 34, 34, 5)
            poly(s, (226, 218, 196), [(x - 15, WALL_B - 36), (x, WALL_B - 41), (x, WALL_B - 35), (x - 15, WALL_B - 31)]); poly(s, (204, 194, 170), [(x + 15, WALL_B - 36), (x, WALL_B - 41), (x, WALL_B - 35), (x + 15, WALL_B - 31)])
            for i in range(3): rect(s, (120, 50, 56), x - 12, WALL_B - 35 + i * 2, 8, 1); rect(s, (120, 50, 56), x + 4, WALL_B - 35 + i * 2, 8, 1)
        elif kind == 'banner':
            rect(s, (60, 44, 34), x - 12, 14, 24, 3); poly(s, (124, 28, 46), [(x - 10, 17), (x + 10, 17), (x + 10, 66), (x, 58), (x - 10, 66)]); rect(s, (190, 138, 84), x - 10, 17, 20, 2)
            glyph(s, 'eye', x, 36, (240, 200, 110))
        elif kind == 'deadtree':
            rect(s, (40, 32, 34), x - 3, 50, 6, 58)
            for _ in range(5):
                bx = x + rng.randint(-2, 2); by = rng.randint(56, 92); ex = x + rng.randint(-28, 28); ey = rng.randint(28, 56); pygame.draw.line(s, (40, 32, 34), (bx, by), (ex, ey), 2)
                rect(s, (224, 234, 246), ex, ey - 1, 3, 1)
def note_papers(s, R):
    for (nx, ny, lab, lines) in R['notes']:
        if lab in R.get('nopaper', ()): continue
        rect(s, (230, 224, 206), nx - 5, 80, 10, 13); rect(s, (110, 100, 90), nx - 3, 83, 6, 1); rect(s, (110, 100, 90), nx - 3, 86, 6, 1); rect(s, (110, 100, 90), nx - 3, 89, 4, 1)
def crack(s, x, y, col, rng):
    pts = [(x, y)]
    for k in range(rng.randint(3, 6)): x += rng.randint(-9, 9); y += rng.randint(-3, 3); pts.append((x, clamp(y, WALL_B + 3, H - 2)))
    pygame.draw.lines(s, col, False, pts, 1)

def draw_house(s, hx, hw, hh, kind, rng):
    top = WALL_B - hh; x0 = hx - hw // 2; roof = (44, 38, 50)
    rect(s, (88, 70, 64), x0, top, hw, hh)
    for px in range(x0 + 6, x0 + hw, 6): pygame.draw.line(s, (70, 54, 50), (px, top), (px, WALL_B - 1), 1)
    rect(s, (214, 226, 240), x0, WALL_B - 6, hw, 6)
    poly(s, roof, [(x0 - 7, top + 4), (hx, top - 24), (x0 + hw + 7, top + 4)]); poly(s, (226, 234, 244), [(x0 - 7, top + 4), (hx, top - 24), (hx, top - 20), (x0 - 2, top + 3)]); poly(s, (226, 234, 244), [(x0 + hw + 7, top + 4), (hx, top - 24), (hx, top - 20), (x0 + hw + 2, top + 3)])
    rect(s, (50, 44, 50), hx + hw // 4, top - 22, 7, 16); rect(s, (226, 234, 244), hx + hw // 4 - 1, top - 24, 9, 3)
    for i in range(8):
        ix = x0 - 4 + i * (hw + 8) // 7; pygame.draw.line(s, (206, 224, 240), (ix, top + 4), (ix, top + 4 + rng.randint(3, 8)), 1)
    for k, wx in enumerate((x0 + 9, x0 + hw - 24)):
        lit = kind == 'lit' and k == 0
        rect(s, (60, 50, 48), wx - 2, top + 12, 18, 20); rect(s, (255, 206, 120) if lit else (14, 16, 24), wx, top + 14, 14, 16)
        pygame.draw.line(s, (60, 50, 48) if lit else (140, 160, 190), (wx + 7, top + 14), (wx + 7, top + 29), 1); pygame.draw.line(s, (60, 50, 48) if lit else (140, 160, 190), (wx, top + 22), (wx + 13, top + 22), 1)
        if not lit and rng.random() < .4: pygame.draw.line(s, (200, 220, 240), (wx, top + 14), (wx + 13, top + 29), 1)
    dc = (6, 6, 8) if kind == 'open' else ((120, 84, 52) if kind == 'lit' else (26, 20, 20))
    rect(s, (50, 40, 38), hx - 8, WALL_B - 28, 16, 28); rect(s, dc, hx - 6, WALL_B - 26, 12, 26)
    if kind == 'open': rect(s, (214, 226, 240), hx - 6, WALL_B - 8, 12, 8)
    pygame.draw.ellipse(s, (226, 236, 248), (hx - 18, WALL_B - 6, 36, 9))
def build_village(R):
    w = R['w']; rng = random.Random(R['seed']); s = pygame.Surface((w, H)).convert()
    for y in range(H): pygame.draw.line(s, mixc((10, 16, 38), (74, 96, 130), min(1.0, y / float(WALL_B))), (0, y), (w, y))
    for _ in range(w // 9): s.set_at((rng.randint(0, w - 1), rng.randint(0, 56)), (200, 210, 230))
    mx = R.get('moonx', 400)
    pygame.draw.circle(s, (60, 76, 110), (mx, 34), 30); pygame.draw.circle(s, (120, 138, 170), (mx, 34), 24); pygame.draw.circle(s, (226, 234, 244), (mx, 34), 19)
    for dx, dy, r in ((-6, -4, 4), (5, 4, 4), (-2, 8, 2)): pygame.draw.circle(s, (186, 198, 216), (mx + dx, 34 + dy), r)
    x = 0
    while x < w:
        th = rng.randint(34, 64); tw = rng.randint(14, 22); base = WALL_B - 4
        for i in range(3):
            ty = base - th + i * (th // 3); poly(s, (24, 38, 60), [(x, ty), (x - tw // 2 + i * 2, ty + th // 2), (x + tw // 2 - i * 2, ty + th // 2)])
        x += rng.randint(10, 20)
    for (hx, hw, hh, kind) in R['houses']: draw_house(s, hx, hw, hh, kind, rng)
    for y in range(WALL_B, H): pygame.draw.line(s, mixc((212, 224, 240), (160, 178, 204), (y - WALL_B) / 72.0), (0, y), (w, y))
    for _ in range(w // 14):
        ex = rng.randint(0, w); ey = rng.randint(WALL_B + 4, H - 4); pygame.draw.ellipse(s, (232, 240, 250), (ex, ey, rng.randint(12, 34), rng.randint(3, 6)))
    for _ in range(w // 20): rect(s, (140, 158, 186), rng.randint(0, w), rng.randint(WALL_B + 6, H - 3), rng.randint(2, 4), 1)
    draw_decor(s, R, None, rng)
    for x in range(40, w, 90):
        if rng.random() < .6: rect(s, (60, 48, 50), x, WALL_B + 2, 3, 8); rect(s, (60, 48, 50), x + 14, WALL_B + 2, 3, 8); rect(s, (70, 56, 56), x - 2, WALL_B + 4, 22, 2); rect(s, (226, 236, 248), x - 2, WALL_B + 2, 22, 2)
    note_papers(s, R)
    return s
def build_room(R):
    if R.get('village'): return build_village(R)
    if R.get('fun'): return build_fun_world(R)
    T = THEMES[R['theme']]; w = R['w']; rng = random.Random(R['seed']); wood = T.get('wood')
    s = pygame.Surface((w, H)).convert()
    for y in range(WALL_B): pygame.draw.line(s, mixc(T['wall_top'], T['wall'], min(1.0, y / 70.0)), (0, y), (w, y))
    if wood:
        sc_ = mixc(T['wall_top'], T['grout'], .55)
        for x in range(0, w, 9): pygame.draw.line(s, sc_, (x, 14), (x, WALL_B - 6), 1)
        rect(s, mixc(T['wall'], T['grout'], .4), 0, 70, w, WALL_B - 76); rect(s, T['cap'], 0, 68, w, 3); rect(s, T['grout'], 0, 71, w, 1)
        for x in range(0, w, 9): pygame.draw.line(s, mixc(T['wall'], T['grout'], .7), (x, 72), (x, WALL_B - 7), 1)
    elif T.get('brick'):
        bc = mixc(T['wall'], T['grout'], .5)
        for y in range(16, WALL_B, 8):
            pygame.draw.line(s, bc, (0, y), (w, y)); off = (y // 8 % 2) * 12
            for x in range(-off, w, 24): pygame.draw.line(s, bc, (x, y), (x, y + 7))
    if T.get('yellow'):
        for x in range(0, w, 12): pygame.draw.line(s, mixc(T['wall'], T['grout'], .35), (x, 12), (x, WALL_B - 6), 2)
        for x in range(6, w, 12): pygame.draw.line(s, mixc(T['wall'], (244, 226, 134), .4), (x, 12), (x, WALL_B - 6), 1)
        for _ in range(w // 36):
            sx = rng.randint(0, w); sy = rng.randint(14, 60); rect(s, mixc(T['wall'], T['base'], .35), sx, sy, rng.randint(2, 4), rng.randint(14, 40))
    rect(s, T['ceil'], 0, 0, w, 12)
    if wood:
        for x in range(0, w, 28): rect(s, mixc(T['ceil'], T['cap'], .18), x, 0, 4, 12)
        rect(s, mixc(T['ceil'], T['cap'], .3), 0, 10, w, 2)
    x = 0
    while x < w and not T.get('yellow'):
        n = rng.randint(4, 14); rect(s, T['ceil'], x, 12, n, rng.randint(2, 8)); x += n
    if T.get('yellow'):
        for x in range(0, w, 20): pygame.draw.line(s, T['grout'], (x, 0), (x, 11), 1)
        for x in range(40, w, 120): rect(s, (246, 244, 206), x, 3, 44, 6); rect(s, (255, 255, 238), x + 2, 4, 40, 2)
    wc = dict((hx_, mixc(T['glass'], c_, .45)) for hx_, c_ in R.get('hourwins', []))
    for cx in R['windows']:
        if wood: draw_shoji(s, cx, T, rng, wc.get(cx))
        else: draw_window(s, cx, T, rng, wc.get(cx))
    for cx in R['columns']:
        if wood: draw_wcolumn(s, cx, T, rng)
        else: draw_column(s, cx, T, rng)
    draw_decor(s, R, T, rng); note_papers(s, R)
    rect(s, mixc(T['cap'], T['base'], .4), 0, WALL_B - 6, w, 2); rect(s, T['base'], 0, WALL_B - 4, w, 4)
    if wood:
        for y in range(WALL_B, H, 12):
            x = -rng.randint(0, 40)
            while x < w:
                bl = rng.randint(36, 80); c = T['fa'] if (y // 12) % 2 == 0 else T['fb']; j = rng.randint(-8, 8)
                rect(s, tuple(clamp(v + j, 0, 255) for v in c), x, y, bl, 12); pygame.draw.line(s, T['grout'], (x, y), (x, y + 11), 1)
                if rng.random() < .5: pygame.draw.line(s, T['grout'], (x + 4, y + 5), (x + rng.randint(10, 26), y + 5), 1)
                x += bl
            pygame.draw.line(s, T['grout'], (0, y), (w, y), 1)
    else:
        tw, th = 24, 14
        for y in range(WALL_B, H, th):
            for x in range(0, w, tw):
                c = T['fa'] if ((x // tw + (y - WALL_B) // th) % 2 == 0) else T['fb']; j = rng.randint(-5, 5)
                rect(s, tuple(clamp(v + j, 0, 255) for v in c), x, y, tw, th)
        for y in range(WALL_B, H, th): pygame.draw.line(s, T['grout'], (0, y), (w, y))
        for x in range(0, w, tw): pygame.draw.line(s, T['grout'], (x, WALL_B), (x, H))
    for _ in range(w // 80): crack(s, rng.randint(0, w), rng.randint(WALL_B + 8, H - 6), T['base'], rng)
    for _ in range(w // 60):
        x = rng.randint(0, w - 8); y = rng.randint(WALL_B + 6, H - 4); rect(s, T['base'], x, y, rng.randint(2, 5), rng.randint(1, 3))
    return s

