def pr(tw, th, zh, top, front, hi=None):
    w = tw * TS; h = th * TS; g = sprite(w, h + zh)
    rect(g, front, 0, h, w, zh); rect(g, mixc(front, (0, 0, 0), .35), 0, h + zh - 2, w, 2); rect(g, top, 0, 0, w, h); rect(g, hi or mixc(top, WHITE, .25), 0, 0, w, 1)
    rect(g, mixc(top, (0, 0, 0), .3), 0, h - 1, w, 1); return g
