_tsc = {}
def td_sprite(o):
    k = o['k']; key = (k, o['tw'], o['th'], o['var'], o['col'])
    im = _tsc.get(key)
    if im is None:
        if k == 'pine': im = PINES[o['var'] % 3]
        elif k == 'deadtree': im = DEADT[o['var'] % 2]
        else: im = build_obj(o)
        _tsc[key] = im
    return im

