class TMon(object):
    def __init__(s, kind, x, y, rad, chase=False):
        s.kind = kind; s.hx = float(x); s.hy = float(y); s.x = float(x); s.y = float(y); s.rad = rad; s.alive = True; s.dying = 0.0; s.t = random.random() * 6; s.stun = 0.0
        s.mode = 'chase' if chase else ('sleep' if kind == 'doll' else 'patrol'); s.mt = 0.0; s.tx = float(x); s.ty = float(y); s.vx = 0.0; s.vy = 0.0; s.f = 0; s.stuck = 0.0
