def img_alpha(im, a):
    c = im.copy(); c.set_alpha(clamp(a, 0, 255)); return c
def build_ghost(kind, f):
    if kind == 'tobias': g = sprite(14, 22); bc = (186, 214, 244, 255); w_ = 5
    elif kind == 'elara': g = sprite(16, 30); bc = (244, 214, 190, 255); w_ = 6
    else: g = sprite(14, 24); bc = (200, 226, 250, 255); w_ = 5
    h_ = g.get_height(); cxx = g.get_width() // 2
    pygame.draw.ellipse(g, bc, (cxx - w_, 1, w_ * 2, w_ * 2 + 2)); rect(g, bc, cxx - w_, w_ + 2, w_ * 2, h_ - w_ - 6)
    for i in range(4): rect(g, bc, cxx - w_ + i * (w_ * 2) // 4, h_ - 5 + ((i + f) % 2) * 2, (w_ * 2) // 4, 4)
    rect(g, (30, 40, 70, 255), cxx - 3, 5, 2, 3); rect(g, (30, 40, 70, 255), cxx + 1, 5, 2, 3)
    if kind == 'elara': rect(g, (150, 110, 96, 255), cxx - w_, 2, 2, h_ - 10); rect(g, (150, 110, 96, 255), cxx + w_ - 2, 2, 2, h_ - 10)
    return g
