ICON_COL = {'ROPE': (200, 160, 100), 'SCARF': (224, 56, 66), 'IRON KEY': (176, 180, 200), 'BRASS KEY': (230, 180, 80), 'BUCKET': (130, 146, 170), 'RED STAR': (246, 90, 100), 'BLUE STAR': (96, 156, 255),
            'WHITE STAR': (252, 252, 255), 'COUNCIL SEAL': (220, 180, 96), 'FUSE': (250, 224, 84), 'LEDGER PAGE': (240, 230, 200), 'CELL KEY': (150, 210, 170), "GRANDMA'S LANTERN": (255, 214, 120), 'PAGE': (240, 230, 200), 'SEAL I': (220, 180, 96), 'SEAL II': (200, 150, 110), 'SEAL III': (180, 160, 200), 'SEAL IV': (230, 110, 110), 'RED FUSE': (240, 80, 80), 'BLUE FUSE': (90, 150, 255), 'GREEN FUSE': (90, 220, 130), 'PAGE I': (240, 230, 200), 'PAGE II': (240, 226, 190), 'PAGE III': (236, 220, 180)}
def build_icon(name):
    g = sprite(10, 10); c = ICON_COL.get(name, (230, 230, 240)); dk = mixc(c, (0, 0, 0), .5)
    if 'KEY' in name: pygame.draw.circle(g, c, (3, 3), 3); rect(g, (0, 0, 0, 0), 2, 2, 2, 2); rect(g, c, 5, 3, 4, 2); rect(g, c, 8, 5, 1, 3); rect(g, c, 6, 5, 1, 2)
    elif 'STAR' in name: poly(g, c, [(5, 0), (6, 4), (10, 5), (6, 6), (5, 10), (4, 6), (0, 5), (4, 4)])
    elif name == 'ROPE': pygame.draw.circle(g, c, (5, 5), 4, 2); pygame.draw.circle(g, dk, (5, 5), 1)
    elif name == 'SCARF': rect(g, c, 1, 2, 8, 3); rect(g, c, 2, 5, 3, 4); rect(g, dk, 1, 4, 8, 1)
    elif name == 'BUCKET': poly(g, c, [(1, 3), (9, 3), (8, 9), (2, 9)]); rect(g, dk, 1, 3, 8, 1)
    elif 'SEAL' in name: pygame.draw.circle(g, c, (5, 5), 4); glyph(g, 'eye', 5, 5, dk)
    elif 'FUSE' in name: rect(g, (210, 210, 220), 3, 1, 4, 8); rect(g, c, 3, 3, 4, 4); rect(g, dk, 4, 0, 2, 1)
    elif 'PAGE' in name: rect(g, c, 2, 0, 6, 10); rect(g, dk, 3, 2, 4, 1); rect(g, dk, 3, 4, 4, 1); rect(g, dk, 3, 6, 3, 1)
    elif 'LANTERN' in name: rect(g, (120, 90, 52), 2, 2, 6, 7); rect(g, c, 3, 3, 4, 5); rect(g, (60, 50, 44), 4, 0, 2, 2)
    else: pygame.draw.circle(g, c, (5, 5), 4)
    return finish(g, (10, 10, 14))
ICONS = dict((k, build_icon(k)) for k in ICON_COL); ICONS['?'] = build_icon('?')
TDB = {}                                                              # map builders by name
