def td_map(name):
    if name not in _tdm: _tdm[name] = TDB[name]().finish()
    return _tdm[name]

SOKO = ['##########', '#        #', '# $   #. #', '#  $  #  #', '# $ .   .#', '#        #', '##########']
def map_archive():
    M = TMap('archive', 46, 34)
    M.sty = {'a': dict(fa=(78, 98, 110), fb=(68, 88, 102), pat='stoneflag', grout=(36, 50, 60)), 'b': dict(fa=(92, 118, 124), fb=(84, 108, 118), pat='tile', grout=(44, 62, 72))}
    M.wp = dict(face=(74, 98, 106), top=(36, 56, 66), line=(46, 70, 80), kind='brick', void=(8, 12, 16)); M.spawn = (8, 28)
    M.room('THE ENTRY HALL', 3, 24, 12, 8, 'a'); M.room('THE GALLERY OF OATHS', 17, 22, 14, 8, 'a'); M.room('THE OATH CHAMBER', 21, 11, 8, 5, 'b'); M.room('THE SEALED ANNEX', 37, 22, 8, 8, 'a')
    M.hall(15, 26, 2, 2, 'a'); M.hall(17, 16, 2, 6, 'a'); M.hall(17, 15, 4, 1, 'a'); M.hall(31, 25, 6, 3, 'a')
    for yy, row in enumerate(SOKO):                                              # the puzzle room has a few inner walls
        for xx, ch in enumerate(row):
            if ch == '#' and 0 < yy < 6 and 0 < xx < 9: M.G[10 + yy][20 + xx] = 1
    for yy, row in enumerate(SOKO):
        for xx, ch in enumerate(row):
            if ch == '$': M.o('tablet', 20 + xx, 10 + yy, push=True, var=(xx + yy) % 3, id='tab%d' % len(M.objs))
            if ch in '.': M.o('plate', 20 + xx, 10 + yy, solid=False, flat=True); M.plates.append((20 + xx, 10 + yy))
    M.extra['plate_fx'] = {'hide': ['oathgate'], 'open': True, 'sfx': 'open', 'say': 'THREE OATHS SIT ON THREE SEALS. SOMEWHERE, AN IRON GATE GROANS OPEN.', 'talk': [('EMBER', 'The oaths are kept. Hurry, the walls are starting to turn yellow...')]}
    M.o('gate', 31, 25, 1, 3, id='oathgate', var=1, act={'t': 'say', 'say': 'THE GATE OF THE SEALED ANNEX. IT OPENS WHEN THE OATH TABLETS REST ON THEIR SEALS.'}, r=30)
    M.o('lectern', 17, 16, id='reset', r=30, act={'t': 'reset'})
    M.note(19, 24, 'OATH MARKER', ['A marker at the foot of the Oath Chamber stairs.', 'If the tablets ever get stuck, touch the lectern in the corridor and they will slide back.'])
    M.o('exit', 40, 21, 2, 1, solid=False, flat=True, act={'t': 'exit'}, iy=22 * TS + 4, r=30)
    M.note(8, 24, 'OATH SCRAP', ['THE COUNCIL SWORE THREE OATHS, AND CARVED EACH ON A STONE TABLET.', 'THE TABLETS WERE NEVER MEANT TO BE CARRIED. ONLY PUSHED.', 'WALK INTO A TABLET AND HOLD YOUR DIRECTION. A TABLET CANNOT BE PULLED.'])
    M.note(24, 22, 'TORN PAGE', ['"EVERY OATH MUST REST ON ITS OWN SEAL BEFORE THE ANNEX WILL OPEN."', 'The rest is eaten by damp.']); M.note(28, 22, 'CARVED STONE', ['Three sleeping tablets: an eye, a heart, a tooth.', 'Three round seals set in the chamber floor, waiting.'])
    M.note(41, 22, 'COUNCIL OATH', ['"WE SWORE TO SEE ALL, SPEAK LITTLE, FEEL NOTHING, AND NEVER REMEMBER."', 'Someone has scratched a tiny crying face below.'])
    for tx, ty in ((5, 25), (12, 25), (19, 23), (29, 23), (39, 23), (43, 29)): M.o('pillar', tx, ty, var=0)
    for tx in (6, 10, 20, 26, 40): M.wd('window', tx, 21 if tx > 17 else 23, tint=(70, 110, 130)) if False else None
    for tx, ty in ((5, 23), (12, 23), (22, 21), (27, 21), (23, 10), (26, 10), (39, 21)): M.wd('lamp', tx, ty, tint=(120, 230, 230)); M.lamp(tx, ty + 2, 40, (110, 180, 200))
    M.o('shelf', 4, 29, 3, 1); M.o('shelf', 10, 29, 3, 1); M.o('table', 23, 26, 3, 2)
    M.mon('shadow', 8, 30, 3); M.mon('shadow', 24, 28, 3)
    return M
TDB['archive'] = map_archive

def map_cellar():
    M = TMap('cellar', 44, 36)
    M.sty = {'a': dict(fa=(98, 66, 76), fb=(84, 54, 64), pat='stoneflag', grout=(52, 32, 42)), 'b': dict(fa=(86, 56, 66), fb=(76, 48, 58), pat='stoneflag', grout=(46, 28, 36))}
    M.wp = dict(face=(112, 72, 78), top=(60, 34, 44), line=(70, 40, 50), kind='brick', void=(10, 6, 10)); M.spawn = (7, 31)
    M.room('THE STAIR LANDING', 3, 28, 10, 6, 'a'); M.room('THE EYE HALL', 16, 26, 14, 8, 'a'); M.room('THE COUNCIL CHAMBER', 14, 6, 16, 13, 'a')
    M.room('FIRST SEAT', 2, 20, 9, 6, 'b'); M.room('SECOND SEAT', 2, 8, 9, 8, 'b'); M.room('THIRD SEAT', 34, 26, 9, 7, 'b'); M.room('FOURTH SEAT', 34, 14, 9, 8, 'b')
    for r in ((13, 29, 3, 3), (21, 19, 3, 7), (6, 26, 3, 2), (5, 16, 3, 4), (30, 28, 4, 3), (37, 22, 3, 4)): M.hall(*r, st='a')
    M.o('gate', 5, 17, 3, 1, id='webgate', var=3, act={'t': 'say', 'say': 'THORNS OF DRIED INK BLOCK THE WAY. THEY HATE LIGHT.'}, pulse={'r': 46, 'fx': {'hide_self': True, 'sfx': 'open', 'say': 'THE INK-THORNS SHRIVEL IN THE LIGHT.'}})
    M.o('gate', 31, 28, 1, 3, id='irongate', var=1, act={'t': 'stages', 'stages': [{'if': ['item:CELL KEY'], 'fx': {'take': 'CELL KEY', 'hide_self': True, 'sfx': 'open', 'say': 'THE CELL KEY TURNS. THE IRON GATE SWINGS OPEN.'}}], 'else': {'say': 'A LOCKED IRON GATE. THE KEYHOLE IS SHAPED LIKE AN EYE.'}}, r=30)
    M.o('exit', 21, 5, 2, 1, solid=False, flat=True, act={'t': 'exit'}, iy=6 * TS + 4, r=30)
    for i, (nm, tx, ty, extra) in enumerate((('SEAL I', 4, 22, {}), ('SEAL II', 6, 10, {}), ('SEAL III', 38, 29, {}), ('SEAL IV', 38, 16, {'spawn': 3, 'flash': (120, 20, 40), 'shake': .4}))):
        fx = dict(extra); fx['say'] = 'A COUNCIL SEAT. A WAX SEAL RESTS ON THE CUSHION.'
        M.o('chairc', tx, ty, id='seat%d' % i, act={'t': 'pick', 'item': nm, 'fx': fx})
    M.o('item', 8, 22, id='cellkey', act={'t': 'pick', 'item': 'CELL KEY', 'say': 'An iron key with an eye-shaped bow, hanging on a nail.'}, solid=False, r=24)
    M.o('lectern', 21, 9, id='lectern', r=32, act={'t': 'stages', 'stages': [{'if': ['flag:dean_called'], 'fx': {'say': '...'}},
        {'if': ['item:SEAL I', 'item:SEAL II', 'item:SEAL III', 'item:SEAL IV'], 'fx': {'set': ['dean_called'], 'sfx': 'creak', 'say': 'FOUR SEALS PRESSED INTO FOUR DENTS. EVERY EYE IN THE ROOM TURNS TO LOOK AT YOU.', 'call': 'dean_scare'}}], 'else': {'say': 'FOUR DENTS IN THE LECTERN. IT WANTS FOUR COUNCIL SEALS, ONE FROM EACH SEAT.'}})
    M.o('table', 20, 13, 4, 2, act={'t': 'say', 'say': 'A round table with four chairs missing. They are in the cells, one apiece.'}); M.o('rug', 19, 11, 6, 6, solid=False, flat=True, col=(110, 30, 50))
    for tx, ty in ((16, 8), (27, 8), (16, 16), (27, 16), (18, 28), (27, 28)): M.o('pillar', tx, ty, var=0)
    for tx in (19, 24, 28): M.wd('banner', tx, 25); M.lamp(tx, 27, 38, (230, 120, 100))
    for tx in (18, 21, 26): M.wd('eye', tx, 5, tint=(200, 120, 90))
    for tx in (4, 6, 8): M.wd('eye', tx, 7, tint=(200, 120, 90)) if tx != 6 else None
    for tx, ty in ((22, 8), (6, 21), (6, 9), (37, 27), (37, 15)): M.o('brazier', tx + 3 if False else tx, ty, lt=(50, (230, 120, 90)))
    M.note(18, 26, 'COUNCIL SEAL', ['Seven eyes are carved into the wall. Three have been painted over in red.', 'A brass plate: "THE COUNCIL OF THE BELL. FOUR SEATS. ONE LEDGER."'])
    M.note(26, 26, "DEAN'S PLAQUE", ['DEAN. CHIEF LEDGER-KEEPER OF AETHER.', '"A CLEAN LEDGER IS A QUIET CITY."', 'Someone has scratched underneath: "...and a quiet city is a dead one."'])
    M.note(16, 6, 'SEAT RULES', ['EACH COUNCILLOR KEPT A SEAL IN HIS OWN CELL.', 'THE FIRST SITS NEAR THE STAIRS. THE SECOND HIDES BEHIND THORNS. THE THIRD IS LOCKED AWAY. THE FOURTH IS TRAPPED.'])
    M.note(6, 20, 'CELL WALL', ['"I KEPT THE KEY ON THE NAIL WHERE I COULD SEE IT."', 'The rest has been scratched away.']); M.o('chest', 3, 24); M.o('barrel', 3, 9); M.o('crate', 9, 14)
    M.mon('shadow', 22, 30, 5); M.mon('shadow', 25, 12, 4); M.mon('shadow', 38, 18, 3); M.mon('shadow', 8, 31, 3)
    M.extra['dean'] = (22, 11)
    return M
TDB['cellar'] = map_cellar

def map_forest():
    M = TMap('forest', 64, 48, out=True)
    M.sty = {'a': dict(fa=(222, 230, 242), fb=(212, 222, 238), pat='snow'), 'p': dict(fa=(190, 192, 204), fb=(182, 184, 198), pat='path'), 'i': dict(fa=(170, 214, 236), fb=(160, 206, 230), pat='ice')}
    M.wp = dict(void=(16, 28, 34)); M.spawn = (8, 41)
    M.room('THE FOREST EDGE', 3, 36, 12, 9, 'a'); M.room("WOODCUTTER'S CLEARING", 4, 18, 12, 10, 'a'); M.room('THE FROZEN POND', 22, 20, 14, 12, 'a'); M.room('THE COLD CAMPFIRE', 22, 38, 12, 8, 'a')
    M.room('THE HANGING TREE', 24, 4, 12, 10, 'a'); M.room('THE WHISPERING GRAVES', 4, 3, 12, 9, 'a'); M.room('HOLLOWFORD STREET', 46, 6, 12, 28, 'p'); M.room('VILLAGE SQUARE', 44, 34, 16, 9, 'p')
    for r in ((8, 28, 3, 8), (16, 22, 6, 3), (15, 40, 7, 3), (27, 32, 3, 6), (28, 14, 3, 6), (16, 6, 8, 3), (36, 24, 10, 3), (8, 12, 3, 6), (34, 40, 10, 3)): M.hall(*r, st='p')
    M.paint(24, 22, 10, 8, 'i')
    # --- woodcutter's clearing
    M.o('house', 6, 19, 4, 2, var=3, act={'t': 'note', 'lines': ['The woodcutter\'s shed. A pale square on the wall where an axe used to hang.', 'A page nailed to the door: "THE WELL ROPE IS INSIDE. THE ICE CAME EARLY THIS YEAR. - HANS"']}, ix=8 * TS, iy=22 * TS, r=28)
    M.o('item', 8, 25, id='rope', act={'t': 'pick', 'item': 'ROPE', 'say': 'A long coil of rope, stiff with frost. The woodcutter\'s well rope.'}, solid=False, r=24)
    M.o('deadtree', 13, 20, var=1); M.o('rock', 5, 26, 2, 1); M.o('crate', 12, 25); M.o('crate', 13, 25); M.mon('shadow', 11, 23, 4)
    # --- frozen pond: Tobias
    M.o('npc', 31, 20, 1, 1, var='tobias', id='tobias', r=34, act={'t': 'stages', 'stages': [
        {'if': ['flag:scarf_back'], 'fx': {'talk': [('TOBIAS', 'Thank you, Mira. It is the first warm thing I have felt in three winters.'), ('TOBIAS', 'The key is in the well. The ice will melt for your light, but you will need a rope.')]}},
        {'if': ['item:SCARF'], 'fx': {'take': 'SCARF', 'set': ['scarf_back', 'knows_well'], 'sfx': 'lamp', 'talk': [
            ('TOBIAS', 'My scarf! My sister knitted it. Red, because red is easy to find in the snow.'), ('TOBIAS', 'The night the Council came, they threw the gate key of the last house down the village well. The ice sealed it.'),
            ('TOBIAS', 'Ice fears light. Melt it with yours, then lower something down. The woodcutter had a rope in his shed.'), ('MIRA', 'The well, the shed, then the glowing house. I can do that.')]}},
        {'if': ['flag:met_tobias'], 'fx': {'talk': [('TOBIAS', 'My red scarf... I lost it in the north, by the hanging tree. I am scared to go there.')]}}],
        'else': {'set': ['met_tobias'], 'talk': [('TOBIAS', '...You are looking at me. Nobody has looked at me in three winters.'), ('MIRA', 'Hello. I am Mira. Who are you?'),
            ('?', [('ARE YOU A GHOST?', [('TOBIAS', 'I think so. I was seven. I came to the pond to skate and then the bell rang... and I just stayed.')]), ('WHY ARE YOU CRYING?', [('TOBIAS', 'I lost my scarf. It was the last thing my sister gave me.')])]),
            ('TOBIAS', 'If you find my red scarf, I will tell you a secret about the glowing house. It hangs in the north, where the old tree stands.')]}})
    M.o('pine', 21, 21, var=0); M.o('rock', 36, 29, 2, 1); M.o('rock', 22, 31); M.mon('shadow', 28, 26, 5)
    M.o('sign', 26, 24, act={'t': 'note', 'lines': ['Skate marks cross the ice in a spiral.', 'They stop in the middle. There are no footprints leading away.']}, solid=False, flat=False)
    # --- campfire: Elara
    M.o('campfire', 27, 41, id='fire', lt=(64, (255, 170, 90)), lt_if=['flag:fire_lit'], act={'t': 'stages', 'stages': [{'if': ['flag:fire_lit'], 'fx': {'say': 'The fire crackles softly.'}}], 'else': {'say': 'A cold campfire. Ash and half-burnt logs. Light might wake it.'}},
        pulse={'r': 50, 'fx': {'set': ['fire_lit'], 'show': ['elara'], 'sfx': 'lamp', 'say': 'THE FIRE CATCHES! SOMEONE STANDS UP BESIDE IT.'}})
    M.o('npc', 30, 41, 1, 1, var='elara', id='elara', hid=True, r=34, act={'t': 'stages', 'stages': [
        {'if': ['flag:met_elara'], 'fx': {'heal': True, 'sfx': 'lamp', 'say': 'ELARA WARMS YOUR HANDS. HEARTS RESTORED.', 'talk': [('ELARA', 'Rest by the fire whenever you need. Tobias is my little brother. Please find his scarf.')]}}],
        'else': {'set': ['met_elara'], 'heal': True, 'talk': [('ELARA', 'You lit the fire. I thought no one would ever do that again.'), ('MIRA', 'Who are you?'),
            ('ELARA', 'Elara. I was eleven. The Council took the children of Hollowford, the youngest first, and fed our names to the bell.'),
            ('?', [('WHY DID NOBODY STOP THEM?', [('ELARA', 'Our parents were told it was a blessing. By the time they understood, the whole village was gone.')]), ('WHERE DID THEY TAKE YOU?', [('ELARA', 'Under the mountain. The Library of Names. That is where the last house leads, if you have the key.')])]),
            ('ELARA', 'My brother Tobias waits by the frozen pond. He lost his scarf somewhere in the north. Be kind to him.')]}})
    M.o('rock', 23, 39, 2, 1); M.o('deadtree', 32, 39); M.mon('shadow', 28, 44, 4)
    # --- hanging tree
    M.o('deadtree', 29, 6, var=0); M.o('item', 30, 8, id='scarf', act={'t': 'pick', 'item': 'SCARF', 'say': 'A red scarf, frozen stiff on a dead branch. It still smells like wool and bread.'}, solid=False, r=24)
    M.o('rock', 26, 11, 2, 1); M.o('rock', 33, 5); M.mon('shadow', 27, 9, 4); M.mon('shadow', 33, 9, 4)
    M.trig('glade', 25, 5, 10, 8, [('VOICE', 'Something red flutters in the dead branches. Careful. The wind here has teeth.')], fx=None)
    # --- whispering graves (story)
    for i, (tx, ty, t1, t2) in enumerate(((6, 5, 'TOBIAS, 7', 'Fresh snow keeps falling on this one, and never settles.'), (8, 5, 'ELARA, 11', 'A paper star hangs from the cross. It turns without wind.'), (10, 5, 'MARTA, 9', 'Someone left a wooden horse here.'),
                                          (12, 5, 'JONAH, 8', 'The cross is carved with a very small knife.'), (14, 5, 'LINA, 10', 'Frozen flowers. Three winters old, and still blue.'))):
        M.o('grave', tx, ty, act={'t': 'note', 'lines': ['Name carved on the stone: ' + t1 + '.', t2]}, solid=True)
    M.trig('graves', 5, 4, 10, 5, [('MIRA', 'So many little stones. They all have names... and no dates.'), ('VOICE', 'The Council never wrote when they ended. Names stay, even when the ones who carried them fold away.'),
                                    ('VOICE', 'Five of nine rest here. The rest are scattered across the Library of Names. Remember them, Mira.')])
    M.o('deadtree', 5, 9); M.o('rock', 14, 9, 2, 1)
    # --- village street
    M.o('house', 46, 12, 5, 2, var=0); M.o('house', 53, 12, 5, 2, var=0)
    M.o('gate', 51, 13, 2, 1, id='vgate', var=1, act={'t': 'stages', 'stages': [{'if': ['item:IRON KEY'], 'fx': {'take': 'IRON KEY', 'hide_self': True, 'open': True, 'set': ['gate_open'], 'say': 'THE KEY TURNS. THE GATE SWINGS OPEN.'}}], 'else': {'say': 'AN IRON GATE. A KEYHOLE THE SIZE OF A TOOTH. THE KEY IS SOMEWHERE ELSE IN THE VILLAGE.'}}, r=34)
    M.o('house', 49, 6, 8, 3, id='glow', var=2, act={'t': 'exit'}, ix=53 * TS, iy=9 * TS + 6, r=34, lt=(70, (255, 200, 120)))
    M.o('house', 46, 16, 5, 2, var=1); M.o('house', 53, 19, 5, 2, var=0); M.o('house', 46, 23, 5, 2, var=1); M.o('house', 53, 26, 5, 2, var=0); M.o('house', 46, 29, 5, 2, var=0)
    M.o('sign', 51, 31, act={'t': 'note', 'lines': ['"HOLLOWFORD - POPULATION 212".', 'Someone scratched the number out. Beneath it, in chalk: 0.']})
    M.o('sign', 52, 21, act={'t': 'note', 'lines': ['Dinner sits frozen on a table through an open door.', 'Seven bowls. Seven chairs. The soup has turned to grey ice.']})
    M.o('sign', 51, 25, act={'t': 'note', 'lines': ['Children\'s boots stand in a neat row by a door.', 'Snow has drifted knee-deep inside. Nobody has been here for years.']})
    M.o('sign', 52, 15, act={'t': 'note', 'lines': ['A calendar nailed to a door. Every day is crossed out.', 'The last page reads: THE NIGHT THE BELL STOPPED.']})
    M.o('sign', 51, 28, act={'t': 'note', 'lines': ['A cradle rocks, very slowly, in a room with no wind.', 'It stops when you look at it.']})
    M.o('well', 51, 37, 2, 2, id='well', act={'t': 'stages', 'stages': [{'if': ['flag:key_got'], 'fx': {'say': 'The well is empty now. The lullaby has stopped.'}},
        {'if': ['flag:well_open', 'item:ROPE'], 'fx': {'take': 'ROPE', 'give': 'IRON KEY', 'set': ['key_got'], 'sfx': 'open', 'say': 'YOU LOWER THE ROPE... SOMETHING COLD AND HEAVY COMES UP: AN IRON KEY!'}},
        {'if': ['flag:well_open'], 'fx': {'say': 'The ice is gone. Black water far below, and something shining at the bottom. You need something to lower down.'}}],
        'else': {'say': 'THE WELL IS FROZEN SOLID, RINGED WITH TINY BELLS. ICE FEARS LIGHT. PRESS LIGHT CLOSE TO IT.'}},
        pulse={'r': 58, 'fx': {'set': ['well_open'], 'sfx': 'open', 'shake': .4, 'say': 'THE ICE CRACKS AND FALLS AWAY. A LULLABY RISES FROM THE WELL, THEN STOPS.'}}, r=40)
    M.o('deadtree', 46, 39, var=0); M.o('deadtree', 58, 40, var=1); M.o('rock', 45, 41, 2, 1)
    M.mon('shadow', 50, 20, 4); M.mon('shadow', 55, 30, 4); M.mon('shadow', 50, 10, 3)
    M.lamp(53, 10, 70, (255, 200, 120))
    # --- scatter pines inside the clearings (never near paths, notes or objects)
    rng = random.Random(41); occ = set()
    for o in M.objs:
        for dx in range(-2, o['tw'] + 2):
            for dy in range(-2, o['th'] + 2): occ.add((o['tx'] + dx, o['ty'] + dy))
    ptiles = [(x, y) for y in range(M.h) for x in range(M.w) if M.G[y][x] == 0 and M.st[y][x] == 'p']
    near_path = set()
    for (x, y) in ptiles:
        for dx in range(-3, 4):
            for dy in range(-3, 4): near_path.add((x + dx, y + dy))
    for y in range(M.h):
        for x in range(M.w):
            if M.G[y][x] == 0 and M.st[y][x] == 'a' and M.zid[y][x] >= 0 and (x, y) not in occ and (x, y) not in near_path and (x, y) != M.spawn and rng.random() < .11:
                M.o('pine', x, y, var=rng.randint(0, 2)); occ.add((x, y))
    return M
TDB['forest'] = map_forest

# ================================================================== MAPS
def map_house():
    M = TMap('house', 38, 29)
    M.sty = {'a': dict(fa=(176, 128, 88), fb=(166, 118, 80), pat='plank', grout=(110, 74, 52)), 'b': dict(fa=(206, 220, 226), fb=(188, 204, 214), pat='tile', grout=(150, 168, 180)),
             'c': dict(fa=(150, 100, 112), fb=(142, 94, 106), pat='carpet', grout=(110, 70, 84)), 'h': dict(fa=(190, 160, 120), fb=(182, 152, 112), pat='plank', grout=(120, 92, 66))}
    M.wp = dict(face=(188, 156, 168), top=(96, 66, 76), line=(160, 126, 138), kind='paper', void=(16, 12, 20)); M.spawn = (6, 6)
    M.room("MIRA'S ROOM", 2, 2, 11, 9, 'a'); M.room('PARENTS BEDROOM', 2, 17, 11, 9, 'c'); M.room('HALLWAY', 14, 2, 3, 24, 'h'); M.room('BATHROOM', 18, 2, 8, 7, 'b')
    M.room('KITCHEN', 18, 11, 9, 7, 'b'); M.room('DINING ROOM', 28, 11, 8, 7, 'a'); M.room('LIVING ROOM', 18, 19, 18, 8, 'c')
    for (x, y) in ((13, 6), (13, 20)): M.hall(x, y, 1, 3, 'h')
    for (x, y) in ((17, 4), (17, 13), (17, 21)): M.hall(x, y, 1, 3, 'h')
    M.hall(27, 13, 1, 3, 'h')
    for tx, ty, tn in ((5, 1, (60, 80, 150)), (9, 1, (60, 80, 150)), (4, 16, (60, 80, 150)), (10, 16, (60, 80, 150)), (20, 10, (70, 90, 150)), (24, 10, (70, 90, 150)), (30, 10, (70, 90, 150)), (33, 10, (70, 90, 150)), (22, 18, (70, 90, 150)), (28, 18, (70, 90, 150)), (34, 18, (70, 90, 150))):
        if ty == 18: continue
        M.wd('window', tx, ty, tint=tn); M.lamp(tx, ty + 2, 40, (110, 130, 200))
    M.wd('clock', 15, 1); M.wd('painting', 22, 1, tint=(150, 190, 220)); M.wd('painting', 31, 18) if False else None; M.wd('door', 26, 27, tint=(110, 74, 52)); M.wd('painting', 16, 1, tint=(220, 170, 120))
    # Mira's room
    M.o('bed', 3, 3, 2, 2, id='mirabed', col=(92, 122, 184), act={'t': 'sleep'}, r=34); M.o('table', 5, 3, 1, 1); M.lamp(5, 3, 46, (255, 214, 150))
    M.o('desk', 9, 3, 2, 1, act={'t': 'note', 'lines': ['A messy desk. Crayons, glue, a half-built paper lantern.', 'A page says: "WHEN I GROW UP I WILL FIX THE BELL."']}); M.o('chair', 9, 4)
    M.o('shelf', 7, 2, 1, 1, act={'t': 'say', 'say': 'Picture books, a snow globe, and one very worn teddy bear.'}); M.o('toychest', 11, 9, act={'t': 'say', 'say': 'Her toy chest. A music box inside plays three off-key notes.'}); M.o('plant', 2, 9)
    M.o('rug', 5, 6, 4, 3, solid=False, flat=True, col=(150, 90, 130)); M.note(8, 2, 'DRAWINGS', ['Crayon drawing: a small girl holding a lantern, and a huge tower with a bell.', 'Under it, in wobbly letters: "ME AND THE BELL THAT NOBODY RINGS."'])
    # parents' bedroom
    M.o('bed', 4, 18, 3, 2, col=(150, 60, 70)); M.o('table', 3, 18); M.o('table', 7, 18); M.lamp(3, 19, 40, (255, 200, 140))
    M.o('wardrobe', 9, 17, 2, 1, id='wardrobe', r=34, act={'t': 'stages', 'stages': [
        {'if': ['flag:lantern'], 'fx': {'say': 'The wardrobe is empty now, except for dust and old coats.'}},
        {'if': ['item:BRASS KEY'], 'fx': {'take': 'BRASS KEY', 'give': "GRANDMA'S LANTERN", 'set': ['lantern'], 'sfx': 'open', 'talk': [('MIRA', "Grandma's old lantern... it is still warm. Like someone just held it."), ('MIRA', 'If I keep it near me tonight, maybe the dark will stay away.')]}}],
        'else': {'say': 'LOCKED. A tiny brass keyhole. The key must be somewhere in the house.'}})
    M.o('counter', 2, 23, 3, 1, act={'t': 'say', 'say': 'A dresser. One drawer is open and half empty. Someone is packing.'}); M.o('chest', 11, 23, act={'t': 'note', 'lines': ['A suitcase, half packed. Mom\'s scarf on top, Mira\'s winter coat beneath.', 'Packed for two.']})
    M.o('rug', 5, 21, 4, 3, solid=False, flat=True, col=(110, 60, 90)); M.note(7, 17, 'WEDDING PHOTO', ['A wedding photo. Mom and Dad, laughing.', 'Someone has turned it face-down, then turned it back again.'])
    # hallway
    M.o('shelf', 14, 11, 1, 1, act={'t': 'say', 'say': 'A shoe rack. Dad\'s boots are still wet with snow.'}); M.o('plant', 16, 3); M.note(15, 2, 'FAMILY PHOTOS', ['Photos of the three of them at the lake. Nobody is crying in any of them.', 'The last one is from three winters ago.'])
    M.lamp(15, 8, 54, (255, 214, 150)); M.lamp(15, 18, 54, (255, 214, 150))
    # bathroom
    M.o('tub', 19, 2, 3, 2); M.o('sink', 24, 2, act={'t': 'say', 'say': 'The tap drips. Plip... plip... like a tiny clock.'}); M.o('rug', 21, 5, 3, 2, solid=False, flat=True, col=(90, 150, 190)); M.note(22, 2, 'MIRROR', ['Mira looks into the mirror. She looks tired, for eight.', 'Behind her reflection, for a second, a little light flickers.'])
    # kitchen
    M.o('counter', 18, 11, 4, 1); M.o('stove', 22, 11); M.o('jar', 23, 11, id='cookiejar', act={'t': 'stages', 'stages': [{'if': ['flag:got_key'], 'fx': {'say': 'Only crumbs now.'}},
        {'if': [], 'fx': {'give': 'BRASS KEY', 'set': ['got_key'], 'sfx': 'lamp', 'say': 'Under the cookies: a tiny brass key! Mom hides things in here.'}}]}); M.o('fridge', 25, 11, act={'t': 'note', 'lines': ['The fridge is covered in magnets and Mira\'s drawings.', 'One magnet holds a note: "DAD - PLEASE COME HOME BEFORE DINNER. - M."']})
    M.o('table', 21, 14, 3, 2); M.o('chair', 20, 14); M.o('chair', 24, 14); M.o('rug', 19, 15, 1, 1, solid=False, flat=True, col=(150, 80, 80)); M.note(26, 11, 'BROKEN PLATE', ['Pieces of a plate lie swept into a corner.', 'Mom swept them up fast, so Mira wouldn\'t see.']); M.lamp(22, 13, 50, (255, 214, 150))
    # dining room
    M.o('table', 30, 13, 4, 2); M.o('chair', 30, 12); M.o('chair', 33, 12); M.o('chair', 30, 15); M.o('chair', 33, 15); M.o('shelf', 29, 11, 1, 1, act={'t': 'say', 'say': 'Plates, glasses, and a row of Dad\'s empty bottles at the back.'}); M.o('shelf', 35, 11, 1, 1)
    M.note(32, 11, 'FAMILY CALENDAR', ['A calendar. Every Friday is circled in red: DAD HOME LATE.', 'Mira\'s birthday is circled in gold. Nobody wrote a plan beside it.']); M.lamp(32, 14, 60, (255, 214, 150))
    # living room
    M.o('sofa', 28, 24, 4, 1); M.o('table', 29, 22, 2, 1); M.o('shelf', 19, 19, 2, 1); M.o('shelf', 33, 19, 2, 1); M.o('plant', 35, 25); M.o('rug', 23, 21, 6, 4, solid=False, flat=True, col=(120, 70, 100))
    M.o('npc', 25, 22, 1, 1, var='dad', solid=True); M.o('npc', 21, 23, 1, 1, var='mom', solid=True); M.lamp(24, 22, 80, (255, 190, 130)); M.lamp(32, 23, 50, (255, 190, 130))
    M.note(26, 19, 'COAT RACK', ['Mom\'s coat, Dad\'s coat, Mira\'s tiny coat. Side by side.', 'For now.'])
    M.trig('fight', 18, 20, 3, 5, None, fx={'call': 'house_fight'})
    return M
