def map_lasthouse():
    M = TMap('lasthouse', 38, 24)
    M.sty = {'a': dict(fa=(150, 106, 76), fb=(138, 96, 68), pat='plank', grout=(84, 56, 42)), 'b': dict(fa=(176, 146, 110), fb=(166, 136, 100), pat='plank', grout=(100, 76, 56))}
