    M.room('THE LIVING ROOM', 3, 10, 15, 12, 'a'); M.room('THE OBSERVATORY ATTIC', 3, 2, 15, 6, 'b'); M.room('THE KITCHEN', 21, 10, 14, 12, 'b'); M.hall(9, 8, 3, 2, 'a'); M.hall(18, 14, 3, 3, 'a')
    M.o('exit', 6, 9, 2, 1, solid=False, flat=True, act={'t': 'exit'}, iy=10 * TS + 4, r=30)
    for tx, ty in ((5, 9), (14, 9), (7, 1), (13, 1), (24, 9), (31, 9)): M.wd('window', tx, ty, tint=(60, 80, 130)); M.lamp(tx, ty + 2, 36, (110, 130, 200))
    M.o('stove', 3, 10, id='stove', lt=(78, (255, 160, 90)), act={'t': 'stages', 'stages': [{'if': ['flag:got_blue'], 'fx': {'say': 'Cold ashes. The stove is quiet now.'}},
        {'if': ['item:BUCKET'], 'fx': {'take': 'BUCKET', 'set': ['got_blue'], 'give': 'BLUE STAR', 'sfx': 'open', 'say': 'HISS! THE FIRE DIES AND A BLUE SHARD GLINTS IN THE ASH.'}}], 'else': {'say': 'THE STOVE ROARS. SOMETHING BLUE GLINTS IN THE COALS, BUT IT IS FAR TOO HOT TO REACH.'}})
    M.o('shelf', 9, 10, 2, 1, act={'t': 'note', 'lines': ['Jars of dried herbs, labelled in three alphabets.', 'One of the labels is not from any country.']})
    M.o('starmap', 12, 10, 3, 1, id='starmap', act={'t': 'stages', 'stages': [{'if': ['flag:map_done'], 'fx': {'say': 'The star map glows. A line runs from a far star down to this valley.'}}], 'else': {'call': 'place_stars'}}, r=40)
    M.note(16, 10, 'STAR MAP', ['A map of the night sky. A line runs from a far star down to this valley.', 'It ends exactly at the Hollow Bell. Three slots are empty: RED, BLUE, WHITE.'])
    M.o('table', 7, 15, 2, 2); M.o('jar', 7, 14, id='teapot', col=(210, 210, 224), act={'t': 'stages', 'stages': [{'if': ['flag:got_brass'], 'fx': {'say': 'An empty teapot. It still smells of mint.'}}, {'if': [], 'fx': {'set': ['got_brass'], 'give': 'BRASS KEY', 'say': 'Under the lid of the teapot: a little brass key.'}}]})
    M.o('chair', 6, 15); M.o('chair', 9, 15); M.o('rug', 5, 17, 6, 3, solid=False, flat=True, col=(90, 80, 130)); M.o('plant', 16, 20); M.o('chest', 3, 21, act={'t': 'say', 'say': 'Winter blankets, folded very neatly by someone with too many arms.'})
    M.o('npc', 14, 15, 1, 1, var='alien', id='alien', r=34, act={'t': 'stages', 'stages': [
        {'if': ['flag:alien_done'], 'fx': {'talk': [(V, 'Go on, little echo. The cellar is waiting.')]}}, {'if': ['flag:map_done'], 'fx': {'call': 'alien_talk'}},
        {'if': ['flag:met_alien'], 'fx': {'talk': [(V, 'Three shards fell from my sky-map. The red one sleeps in the attic. The blue one fell into the stove. The white one hides in my herb jars.')]}}],
        'else': {'set': ['met_alien'], 'talk': [('MIRA', 'A fire is burning. Someone has been keeping this room warm.'), (V, '...You can see me. Few can, now. Only the very young, and the very dead.'),
            (V, 'Please, little one. My sky-map broke when my ship fell. Three star shards scattered through this house: red, blue and white.'), (V, 'Put them back, and I will tell you everything. The attic stairs are behind me.')]}})
    # attic
    M.o('telescope', 12, 3, act={'t': 'note', 'lines': ['The telescope points at one patch of sky.', 'Through it: three stars, one red, one blue, one white. They hang over the Hollow Mountain.']}); M.o('desk', 8, 3, 2, 1)
    M.o('chest', 5, 4, id='atticchest', act={'t': 'stages', 'stages': [{'if': ['flag:got_red'], 'fx': {'say': 'Empty now.'}}, {'if': ['item:BRASS KEY'], 'fx': {'take': 'BRASS KEY', 'set': ['got_red'], 'give': 'RED STAR', 'sfx': 'open', 'say': 'THE BRASS KEY FITS! A RED SHARD GLOWS INSIDE.'}}],
        'else': {'say': 'A LOCKED CHEST WITH A TINY BRASS KEYHOLE.'}}); M.o('plant', 16, 3); M.o('rug', 6, 4, 4, 3, solid=False, flat=True, col=(70, 70, 130))
    M.note(10, 2, 'SKY NOTES', ['"THE RED STAR IS HIDDEN WHERE MY KEYS WOULD BE LOCKED AWAY."', '"THE BLUE STAR IS TOO HOT TO TOUCH. WATER SOLVES MOST THINGS."', '"THE WHITE STAR IS LABELLED WITH A COUNTRY THAT DOES NOT EXIST."'])
    # kitchen
    M.o('counter', 21, 10, 6, 1); M.note(28, 10, 'HERB LABELS', ['Four jars: THYME, MINT, SALT FROM THE SEA, and one with a label from no country at all.']); M.o('shelf', 30, 10, 4, 1)
    for tx, col, say in ((30, (160, 210, 140), 'Dried thyme.'), (31, (190, 240, 200), 'Dried mint. Smells like cold toothpaste.'), (32, (240, 240, 250), 'Salt from the sea. Crunchy.')):
        M.o('jar', tx, 11, col=col, act={'t': 'say', 'say': say})
    M.o('jar', 33, 11, id='starjar', col=(200, 150, 255), act={'t': 'stages', 'stages': [{'if': ['flag:got_white'], 'fx': {'say': 'An empty jar. The label is a spiral.'}}, {'if': [], 'fx': {'set': ['got_white'], 'give': 'WHITE STAR', 'sfx': 'lamp', 'say': 'THE JAR WITH THE STRANGE LABEL! A WHITE SHARD SITS AMONG THE LEAVES.'}}]})
    M.o('item', 22, 18, id='bucket', act={'t': 'pick', 'item': 'BUCKET', 'say': 'A tin bucket, full of melted snow.'}, solid=False, r=24)
    M.o('table', 26, 15, 3, 2); M.o('chair', 25, 15); M.o('chair', 29, 15); M.o('fridge', 34, 10, act={'t': 'say', 'say': 'A cold box. Inside: a single, perfectly round blue apple.'}); M.o('barrel', 22, 20); M.o('rug', 24, 18, 5, 3, solid=False, flat=True, col=(130, 90, 70)); M.lamp(27, 14, 56, (255, 200, 140))
    M.extra['npc'] = (14, 15)
    return M
