def map_ledger():
    M = TMap('ledger', 52, 34)
    M.sty = {'a': dict(fa=(94, 60, 70), fb=(82, 50, 60), pat='stoneflag', grout=(50, 28, 38)), 'b': dict(fa=(70, 44, 58), fb=(62, 38, 50), pat='stoneflag', grout=(36, 20, 30))}
    M.wp = dict(face=(100, 60, 70), top=(52, 28, 38), line=(64, 36, 46), kind='brick', void=(8, 4, 8)); M.spawn = (25, 28)
    M.room('THE LAST LEDGER', 20, 12, 12, 10, 'a'); M.room('THE BLACK ENTRY', 20, 25, 12, 7, 'b'); M.room('PAGE ROOM OF THE WEST', 3, 13, 9, 8, 'b'); M.room('PAGE ROOM OF THE EAST', 40, 13, 9, 8, 'b'); M.room('PAGE ROOM OF THE NORTH', 18, 1, 16, 5, 'b')
    M.hall(25, 22, 2, 3, 'a'); M.hall(12, 15, 8, 4, 'a'); M.hall(32, 15, 8, 4, 'a'); M.hall(24, 6, 4, 6, 'a')
    M.o('exit', 29, 11, 2, 1, solid=False, flat=True, act={'t': 'exit'}, iy=12 * TS + 4, r=30)
    for nm, tx, ty in (('PAGE I', 4, 14), ('PAGE II', 47, 14), ('PAGE III', 31, 2)):
        M.o('item', tx, ty, id=nm, act={'t': 'pick', 'item': nm, 'say': 'A blank page stained with a child\'s name, crossed out in red. The ink is still wet.'}, solid=False, r=24)
    # crossings: beams that strike on a timer
    for i, (tx, off) in enumerate(((14, 0.0), (17, 1.5))): M.haz.append(dict(o='v', v=tx * TS + 8, a=15 * TS, b=19 * TS, per=3.2, off=off))
    for i, (tx, off) in enumerate(((34, 0.8), (37, 2.3))): M.haz.append(dict(o='v', v=tx * TS + 8, a=15 * TS, b=19 * TS, per=3.2, off=off))
    for i, (ty, off) in enumerate(((8, 0.0), (10, 1.6))): M.haz.append(dict(o='h', v=ty * TS + 8, a=24 * TS, b=28 * TS, per=3.4, off=off))
    M.o('lectern', 25, 14, id='lectern', r=34, act={'t': 'stages', 'stages': [{'if': ['flag:dean_called'], 'fx': {'say': '...'}},
        {'if': ['item:PAGE I', 'item:PAGE II', 'item:PAGE III'], 'fx': {'set': ['dean_called'], 'sfx': 'creak', 'say': 'YOU LAY THE THREE PAGES ON THE LECTERN. THEY CATCH FIRE WITHOUT SMOKE. SOMETHING WAKES.', 'call': 'dean_scare'}}],
        'else': {'say': 'THE LECTERN WANTS THREE CROSSED-OUT PAGES, ONE FROM EACH ROOM BEYOND THE RED LINES.'}})
    M.o('table', 22, 17, 3, 2); M.o('table', 28, 17, 3, 2); M.o('rug', 23, 19, 6, 2, solid=False, flat=True, col=(90, 20, 40)); M.o('inkpile', 21, 13); M.o('inkpile', 30, 13)
    for tx in (22, 29): M.wd('banner', tx, 11); M.lamp(tx, 13, 40, (230, 80, 100))
    for tx, ty in ((22, 25), (30, 25), (21, 30), (30, 30)): M.o('pillar', tx, ty)
    M.note(22, 12, 'LOOSE PAGES', ["Hundreds of pages, each with a child's name crossed out in red.", 'The ink is still wet.']); M.note(27, 12, 'LAST PAGE', ['One page is still blank, except for a single word: MIRA.', 'Beneath it, in tiny neat letters: "SECOND DRAFT."'])
    M.note(22, 25, 'RED LINES', ['THE LEDGER CROSSES THINGS OUT ON A STRICT SCHEDULE.', 'WATCH THE TELLTALE DASHES. WHEN THEY APPEAR, STEP BACK. WHEN THE LINE FLASHES AND FADES, RUN.']); M.note(5, 13, 'WEST WALL', ['Names crossed out in alphabetical order. The pen is still moving.']); M.note(42, 13, 'EAST WALL', ['Names crossed out youngest first.'])
    M.note(20, 1, 'NORTH WALL', ['A single drawn eye, and underneath: "I SEE EVERY NAME."'])
    M.mon('shadow', 8, 18, 3); M.mon('shadow', 26, 3, 5); M.mon('shadow', 25, 20, 4)
    M.extra['dean'] = (26, 17)
    return M
TDB['ledger'] = map_ledger
