def map_library():
    M = TMap('library', 50, 38)
    M.sty = {'a': dict(fa=(88, 96, 122), fb=(76, 84, 110), pat='stoneflag', grout=(44, 48, 66)), 'b': dict(fa=(104, 92, 84), fb=(94, 82, 76), pat='plank', grout=(60, 48, 44))}
    M.wp = dict(face=(96, 104, 124), top=(52, 58, 78), line=(60, 66, 88), kind='brick', void=(8, 8, 14)); M.spawn = (7, 33)
    M.room('THE LONG STAIRS', 3, 30, 10, 6, 'a'); M.room('THE READING HALL', 16, 26, 18, 10, 'b'); M.room('THE AISLES OF NAMES', 6, 4, 38, 18, 'a')
    M.hall(13, 31, 3, 3, 'a'); M.hall(23, 22, 4, 4, 'a')
    M.o('exit', 24, 3, 2, 1, solid=False, flat=True, act={'t': 'exit'}, iy=4 * TS + 4, r=30)
    for y in (7, 11, 15):
        for x in (8, 15, 22, 29, 36): M.o('shelf', x, y, 5, 1)
    ages = (('ELARA', 11, 14, 9), ('LINA', 10, 21, 13), ('TOBIAS', 7, 28, 9), ('MARTA', 9, 35, 13), ('JONAH', 8, 10, 18))
    for nm, age, tx, ty in ages:
        M.o('jar', tx, ty, label='%s, AGE %d' % (nm, age), col=(190, 230, 255), act={'t': 'seq', 'g': 'names', 'key': nm, 'whisper': 'THE JAR HUMS A LULLABY AND GROWS WARM.'}, r=26)
    M.seqs['names'] = {'order': ['TOBIAS', 'JONAH', 'MARTA', 'LINA', 'ELARA'], 'ok': {'open': True, 'say': 'THE LAST JAR SINGS. EVERY NAME IS AWAKE. THE DOOR OPENS.', 'talk': [('EMBER', 'Youngest first. The Council could never forgive a ledger that was not in order.')]},
                       'wrong': {'say': 'THE JARS GO COLD. THE DARK STIRS...', 'spawn': 2}}
    for i, (tx, ty) in enumerate(((20, 5), (30, 20), (8, 20))):
        M.o('candle', tx, ty, id='c%d' % i, act={'t': 'stages', 'stages': [{'if': ['flag:c%d' % i], 'fx': {'say': 'Already lit.'}}], 'else': {'set': ['c%d' % i], 'sfx': 'lamp', 'say': 'THE CANDELABRA CATCHES. THE DARK BACKS AWAY A LITTLE.'}})
    M.o('ledger', 24, 28, id='ledger', act={'t': 'note', 'lines': ["LEDGER OF THE BELL, in the Council's neat hand:", '"Each toll costs one name. Take the youngest first."', 'The last line is smudged: "MIRA, AGE 8. NAME NOT TAKEN. HEART TAKEN INSTEAD."']}, r=30)
    M.o('table', 19, 29, 3, 2); M.o('table', 28, 29, 3, 2); M.o('chair', 18, 29); M.o('chair', 31, 31); M.o('crate', 17, 34); M.o('barrel', 32, 34); M.o('pillar', 20, 33); M.o('pillar', 30, 33)
    M.note(8, 30, 'STAIRS', ['The stairs went down for a long, long time.', 'The air tastes of old ink and older tears.']); M.note(20, 26, 'JARS', ['A shelf of tiny jars. "TOBIAS, AGE 7". "ELARA, AGE 11".', 'A pale light hums a lullaby inside each one.'])
    M.note(30, 26, 'READING RULE', ['THE LEDGER SAYS WHICH NAME GOES FIRST.', 'FIVE JARS STAND IN THE AISLES. EACH LABEL SHOWS A NAME AND AN AGE. READ THEM BY STANDING CLOSE.'])
    for tx in (10, 18, 26, 34, 40): M.wd('window', tx, 3, tint=(60, 70, 120)); M.lamp(tx, 5, 40, (90, 110, 190))
    M.o('pillar', 7, 21); M.o('pillar', 43, 21); M.o('pillar', 7, 5); M.o('pillar', 43, 5)
    M.mon('shadow', 14, 5, 6); M.mon('shadow', 30, 9, 7); M.mon('shadow', 36, 19, 6); M.mon('shadow', 24, 33, 5)
    return M
