        for i in range(3):
            ty = base - th + i * (th // 3); poly(s, col, [(x, ty), (x - tw // 2 + i * 2, ty + th // 2), (x + tw // 2 - i * 2, ty + th // 2)])
        rect(s, col, x - 1, base - 8, 3, 10); x += rng.randint(12, 24)
