# ------------------------------------------------------------------ save / art cache
SAVE_NAME = 'echoes_save.json'
def _save_dirs():
    out = []
    def add(d):
        try:
            if d and d not in out: out.append(d)
        except Exception: pass
    try: add(os.path.dirname(os.path.abspath(__file__)))
    except Exception: pass
    try: add(os.getcwd())
    except Exception: pass
    try: add(os.path.expanduser('~'))
    except Exception: pass
    for d in ('/storage/emulated/0/Download', '/sdcard/Download', '/storage/emulated/0', '/sdcard'):
        add(d)
    try:
        import tempfile; add(tempfile.gettempdir())
    except Exception: pass
    return out
def _can_write(d):
    try:
        if not os.path.isdir(d): return False
        t = os.path.join(d, '.echoes_test')
        with open(t, 'w') as f: f.write('1')
        os.remove(t); return True
    except Exception: return False
SAVE_PATH = None
for _d in _save_dirs():
    if _can_write(_d): SAVE_PATH = os.path.join(_d, SAVE_NAME); break
def _read_json(path):
    with open(path, 'r') as f: d = json.load(f)
    if not isinstance(d, dict): raise ValueError('bad save')
    return d
def load_save():
    d = None
    for cand in [SAVE_PATH] + [os.path.join(x, SAVE_NAME) for x in _save_dirs()]:       # also pick up a save an older version left elsewhere
        try:
            if cand and os.path.exists(cand): d = _read_json(cand); break
        except Exception: continue
    if d is None: return {}
    if d.get('ver', 1) < 2:                      # v8 inserted Dean's cellar at room 3: shift older saves past it
        if d.get('room', 0) >= 3: d['room'] += 1
        d['ver'] = 2
    if d.get('ver', 1) < 3:                      # v9 added three rooms before the Hollow Bell
        if d.get('room', 0) >= 5: d['room'] += 3
        d['ver'] = 3
    if d.get('ver', 1) < 4:                      # v10 added Level Fun at room 7: shift older saves past it
        if d.get('room', 0) >= 7: d['room'] += 1
        d['ver'] = 4
    return d
def write_save(d):
    global SAVE_PATH
    data = json.dumps(d)
    for _ in range(2):
        if SAVE_PATH:
            try:
                tmp = SAVE_PATH + '.tmp'
                with open(tmp, 'w') as f:
                    f.write(data); f.flush()
                    try: os.fsync(f.fileno())
                    except Exception: pass
                os.replace(tmp, SAVE_PATH); return True
            except Exception:
                try:
                    with open(SAVE_PATH, 'w') as f: f.write(data)       # fallback: plain write
                    return True
                except Exception: pass
        SAVE_PATH = None                                                 # this folder does not work: look for another one
        for _d in _save_dirs():
            if _can_write(_d): SAVE_PATH = os.path.join(_d, SAVE_NAME); break
        if not SAVE_PATH: break
    return False
_art = {}
def get_art(i):
    if i not in _art: _art[i] = build_room(ROOMS[i])
    return _art[i]
PILLARS = [build_pillar(k) for k in range(3)]; PILLARS_W = [build_pillar(k + 5, True) for k in range(3)]
