# ------------------------------------------------------------------ entities
class Player(object):
    def __init__(s, x, y):
        s.x = float(x); s.y = float(y); s.dir = 'd'; s.anim = 0.0; s.moving = False; s.hp = 3; s.maxhp = 3; s.energy = 100.0
        s.inv = 0.0; s.kx = 0.0; s.ky = 0.0; s.stepT = 0.0
class Mon(object):
    def __init__(s, kind, x, y, rad, chase=False):
        s.kind = kind; s.hx = float(x); s.x = float(x); s.y = float(y); s.rad = rad; s.alive = True; s.dying = 0.0
        s.t = random.random() * 6; s.stun = 0.0; s.mode = 'chase' if chase else ('sleep' if kind == 'doll' else 'patrol')
        s.mt = 0.0; s.tx = float(x); s.ty = float(y); s.vx = 0.0; s.vy = 0.0; s.f = 0
    def update(s, dt, p, w):
        if s.dying > 0: s.dying -= dt
        if not s.alive: return
        s.t += dt
        if s.stun > 0: s.stun -= dt; return
        d = math.hypot(p.x - s.x, (p.y - s.y) * 1.5)
        if s.kind == 'shadow':
            if d < 84 or (s.mode == 'chase' and d < 220): s.mode = 'chase'
            else: s.mode = 'patrol'
            if s.mode == 'chase':
                tx, ty, sp = p.x, p.y, 32.0
            else:
                s.mt -= dt
                if s.mt <= 0 or math.hypot(s.tx - s.x, s.ty - s.y) < 3:
                    s.tx = clamp(s.hx + random.uniform(-s.rad, s.rad), 12, w - 12); s.ty = random.uniform(FY0, FY1); s.mt = random.uniform(2, 5)
                tx, ty, sp = s.tx, s.ty, 16.0
            dx, dy = tx - s.x, ty - s.y; m = math.hypot(dx, dy) or 1.0
            s.x += dx / m * sp * dt; s.y += dy / m * sp * 0.8 * dt
        else:
            s.mt -= dt
            if s.mode == 'sleep':
                if d < 74: s.mode = 'hop'; s.mt = .5; dx, dy = p.x - s.x, p.y - s.y; m = math.hypot(dx, dy) or 1.0; s.vx = dx / m * 95; s.vy = dy / m * 70
            elif s.mode == 'hop':
                s.x += s.vx * dt; s.y += s.vy * dt; s.f = int(s.t * 10) % 2
                if s.mt <= 0: s.mode = 'rest'; s.mt = 1.1; s.f = 0
            elif s.mt <= 0: s.mode = 'sleep'
        s.x = clamp(s.x, 10, w - 10); s.y = clamp(s.y, FY0, FY1)

# ------------------------------------------------------------------ the game
class Pt(object):
    def __init__(s, x, y): s.x = x; s.y = y

class Game(object):
    def __init__(s):
        s.state = 'title'; s.t = 0.0; s.save = load_save(); s.sound = True; s.sel = 0; s.volume = 0.70; s.settings_from = 'title'; s.settings_sel = 0
        s.fingers = {}; s.kbd = set(); s.ev = []; s.mv = (0.0, 0.0); s.sc = 1.0; s.ox = 0; s.oy = 0
        s.fade = 1.0; s.fade_dir = -1; s.fade_act = None; s.shake = 0.0; s.flash = 0.0; s.fcol = (255, 255, 255)
        s.dlg = []; s.di = 0; s.dch = 0.0; s.dafter = None; s.choice = None; s.csel = 0; s.lastblip = 0
        s.msg = ''; s.msg_t = 0.0; s.banner_t = 0.0; s.parts = []; s.music_on = False
        s.comic = []; s.ci = 0; s.ct = 0.0; s.cafter = None; s.pause_sel = 0
        s.has_heart = False; s.item_t = 0.0; s.item_cb = None; s.snow = [[random.uniform(0, W), random.uniform(0, H), random.uniform(14, 34), random.uniform(0, 6.28)] for _ in range(70)]
        s.p = Player(50, 146); s.R = ROOMS[0]; s.ri = 0; s.mons = []; s.stones = []; s.candles = []; s.obst = []
        s.boss = None; s.pulse_t = 0.0; s.cam = 0.0; s.next_stone = 0; s.door_open = False; s.dead_t = 0.0; s.won_t = 0.0
        s.dean = None; s.tr = None; s.hb_t = 0.0; s.dead_to = None; s.pause_to = 'play'; s.scare_t = 0.0; s.strike_t = 0.0; s.halls = None; s.trial_hard = False; s.buzz_t = 0.0; s.fun = None; s.camy = 0.0; s.fconf = []
    # ---------------- basics
    def sfx(s, name, vol=1.0):
        if s.sound and name in SFX:
            try: SFX[name].set_volume(vol * s.volume); SFX[name].play()
            except Exception: pass
    def say(s, m, t=2.6): s.msg = m; s.msg_t = t
    def btns(s):                                                      # which of the ACT / LIGHT buttons exist right now
        if s.state not in ('play', 'trial') or s.dlg: return ()
        hide = s.R.get('nobtn', ())
        return tuple(n for n in ('act', 'light') if n not in hide)
    def fade_to(s, act): s.fade_dir = 1; s.fade_act = act
    def burst(s, x, y, n, col, sp=50.0):
        for _ in range(n):
            a = random.uniform(0, 6.283); v = random.uniform(.3, 1) * sp
            s.parts.append([x, y, math.cos(a) * v, math.sin(a) * v - 15, random.uniform(.4, .9), col])
    def to_logic(s, px, py): return ((px - s.ox) / s.sc, (py - s.oy) / s.sc)
    # ---------------- input
    def event(s, e):
        T = e.type
        if T == pygame.QUIT: return False
        if T == pygame.KEYDOWN:
            k = e.key
            if k == pygame.K_ESCAPE or k == getattr(pygame, 'K_AC_BACK', -999): s.ev.append(('key', 'back'))
            elif k in (pygame.K_LEFT, pygame.K_a): s.kbd.add('l')
            elif k in (pygame.K_RIGHT, pygame.K_d): s.kbd.add('r')
            elif k in (pygame.K_UP, pygame.K_w): s.kbd.add('u'); s.ev.append(('key', 'up'))
            elif k in (pygame.K_DOWN, pygame.K_s): s.kbd.add('d'); s.ev.append(('key', 'down'))
            elif k in (pygame.K_SPACE, pygame.K_e, pygame.K_RETURN): s.ev.append(('key', 'act'))
            elif k in (pygame.K_q, pygame.K_f, pygame.K_LSHIFT): s.ev.append(('key', 'light'))
        elif T == pygame.KEYUP:
            k = e.key
            for n, ks in (('l', (pygame.K_LEFT, pygame.K_a)), ('r', (pygame.K_RIGHT, pygame.K_d)), ('u', (pygame.K_UP, pygame.K_w)), ('d', (pygame.K_DOWN, pygame.K_s))):
                if k in ks: s.kbd.discard(n)
        elif hasattr(pygame, 'FINGERDOWN') and T == pygame.FINGERDOWN:
            sw, sh = screen.get_size(); s.down(e.finger_id, e.x * sw, e.y * sh)
        elif hasattr(pygame, 'FINGERMOTION') and T == pygame.FINGERMOTION:
            sw, sh = screen.get_size(); s.move(e.finger_id, e.x * sw, e.y * sh)
        elif hasattr(pygame, 'FINGERUP') and T == pygame.FINGERUP:
            s.fingers.pop(e.finger_id, None)
        elif T == pygame.MOUSEBUTTONDOWN and not getattr(e, 'touch', False): s.down('m', e.pos[0], e.pos[1])
        elif T == pygame.MOUSEMOTION and 'm' in s.fingers and not getattr(e, 'touch', False): s.move('m', e.pos[0], e.pos[1])
        elif T == pygame.MOUSEBUTTONUP and not getattr(e, 'touch', False): s.fingers.pop('m', None)
        return True
    def down(s, fid, px, py):
        x, y = s.to_logic(px, py); role = None
        if s.state in ('play', 'trial') and not s.dlg:
            for name, (cx, cy, r) in BTNS.items():
                if name in s.btns() and math.hypot(x - cx, y - cy) <= r + 6: s.ev.append(('key', name)); role = 'btn'; break
        if role is None:
            s.ev.append(('tap', x, y))
            if s.state in ('play', 'trial') and x < W * 0.5: role = 'stick'
        s.fingers[fid] = {'pos': (x, y), 'org': (x, y), 'role': role}
    def move(s, fid, px, py):
        f = s.fingers.get(fid)
        if not f: return
        x, y = s.to_logic(px, py); f['pos'] = (x, y)
        if f['role'] == 'stick':
            dx, dy = x - f['org'][0], y - f['org'][1]; m = math.hypot(dx, dy)
            if m > 22: k = (m - 22) / m; f['org'] = (f['org'][0] + dx * k, f['org'][1] + dy * k)
    def read_inputs(s):
        x = y = 0.0; k = s.kbd
        if 'l' in k: x -= 1
        if 'r' in k: x += 1
        if 'u' in k: y -= 1
        if 'd' in k: y += 1
        for f in s.fingers.values():
            if f['role'] == 'stick':
                dx = f['pos'][0] - f['org'][0]; dy = f['pos'][1] - f['org'][1]; m = math.hypot(dx, dy)
                if m > 3: q = min(1.0, m / 14.0); x += dx / m * q; y += dy / m * q
                break
        m = math.hypot(x, y)
        if m > 1: x /= m; y /= m
        s.mv = (x, y)
    # ---------------- flow
    def new_game(s):
        s.save = {'room': 0, 'ver': 4}; write_save(s.save); s.has_heart = False; s.fade_to(lambda: s.start_room(HOME_I, False))
    def begin_comic(s, panels, after):
        s.state = 'comic'; s.comic = panels; s.ci = 0; s.ct = 0.0; s.cafter = after; s.fade = 1.0; s.fade_dir = -1; s.fade_act = None
    def end_comic(s):
        if s.fade_dir <= 0: s.fade_to(s.cafter)
    def to_title(s): s.state = 'title'; s.save = load_save(); s.fade = 1.0; s.fade_dir = -1; s.sel = 0
    def start_room(s, i, intro=True):
        s.ri = i; R = s.R = ROOMS[i]
        if R.get('td'): return s.td_start(i, intro)
        if R['goal'] == 'dean' and not R.get('final'): s.save.pop('dl', None)
        if i >= 3: s.has_heart = True
        s.p = Player(*R['spawn']); s.p.maxhp = (4 if s.has_heart else 3) - (1 if s.save.get('dl') else 0); s.p.hp = s.p.maxhp; s.cam = clamp(s.p.x - W * .45, 0, R['w'] - W)
        s.mons = [Mon(*e) for e in R['enemies']]
        s.stones = [{'k': k, 'x': x, 'y': y, 'lit': False} for k, x, y in R['stones']]
        s.candles = [{'x': x, 'y': y, 'lit': False} for x, y in R['candles']]
        s.next_stone = 0; s.door_open = (R['goal'] == 'alien' and s.has_heart); s.parts = []; s.pulse_t = 0.0; s.won_t = 0.0; s.boss = None; s.msg_t = 0.0; s.dlg = []; s.choice = None
        s.obst = [(px - 20, by - 6, 40, 10) for px, by in R['pillars']] + [(x - 6, y - 4, 12, 6) for k, x, y in R['stones']] + [(x - 5, y - 3, 10, 5) for x, y in R['candles']]
        if R['goal'] == 'boss':
            s.boss = {'hp': 3, 'state': 'talk', 't': 0.0, 'spawn': 1.5}; s.obst.append((R['bellx'] - 26, 146, 52, 12))
        s.dean = None; s.hb_t = 0.0; s.scare_t = 0.0; s.strike_t = 0.0; s.dead_to = None; s.pause_to = 'play'; s.halls = None; s.trial_hard = bool(R.get('final'))
        if R['goal'] == 'dean': s.dean = {'state': 'hidden', 'a': 1.0, 'x': float(R['dean']['x']), 'y': float(R['dean']['y'])}
        if R.get('halls'): s.halls_round(1)
        s.fun = None
        if R.get('fun'): s.fun_init()
        s.state = 'play'; s.fade = 1.0; s.fade_dir = -1; s.fade_act = None; s.banner_t = 3.0
        if not R.get('home'): s.save['room'] = i; s.save['ver'] = 4; write_save(s.save)
        if R.get('home'): s.home_init(); return
        if R['goal'] == 'boss':
            if intro: s.talk(R['intro'], lambda: s.talk(R['keeper'], s.boss_start))
            else: s.boss_start()
        elif intro: s.talk(R['intro'], lambda: s.say(R['hint'], 4.0))
        else: s.say(R['hint'], 4.0)
    def boss_start(s):
        if s.boss: s.boss['state'] = 'wave'; s.boss['t'] = 0.0; s.say(s.R['hint'], 4.0)
    def talk(s, lines, after=None):
        s.dlg = list(lines); s.di = 0; s.dch = 0.0; s.dafter = after; s.choice = None; s.csel = 0; s.check_choice()
    def check_choice(s):
        if s.dlg and s.di < len(s.dlg) and s.dlg[s.di][0] == '?': s.choice = s.dlg[s.di][1]; s.csel = 0
    def end_talk(s):
        s.dlg = []; s.choice = None; cb = s.dafter; s.dafter = None
        if cb: cb()
    def adv_talk(s):
        if s.choice: return
        spk, txt = s.dlg[s.di]
        if s.dch < len(txt): s.dch = float(len(txt)); return
        s.di += 1; s.dch = 0.0
        if s.di >= len(s.dlg): s.end_talk()
        else: s.check_choice()
    def pick(s, k):
        items = s.choice[k][1]; s.dlg[s.di:s.di + 1] = list(items); s.choice = None; s.dch = 0.0; s.sfx('blip')
    def hurt(s, m):
        p = s.p
        if p.inv > 0: return
        p.hp -= 1; p.inv = 1.5; s.shake = .3; s.flash = .5; s.fcol = (200, 40, 70); s.sfx('hurt'); s.burst(p.x, p.y - 12, 10, RED)
        dx, dy = p.x - m.x, p.y - m.y; d = math.hypot(dx, dy) or 1.0; p.kx = dx / d * 120; p.ky = dy / d * 70
        if p.hp <= 0: s.dead_to = 'trial' if s.state == 'trial' else None; s.state = 'dead'; s.dead_t = 0.0
    def spawn_shadow(s, far=True):
        p = s.p; w = s.R['w']; side = 1 if (p.x < w / 2) else -1
        x = clamp(p.x + side * random.randint(110, 170), 14, w - 14); y = random.uniform(FY0, FY1)
        s.mons.append(Mon('shadow', x, y, 100, True)); s.burst(x, y - 10, 8, (120, 100, 170))
    def do_pulse(s):
        p = s.p; p.energy -= 30; s.pulse_t = .4; s.sfx('pulse')
        for m in s.mons:
            if not m.alive: continue
            if math.hypot(m.x - p.x, (m.y - p.y) * 1.6) < 68:
                if m.kind == 'shadow': m.alive = False; m.dying = .5; s.burst(m.x, m.y - 10, 12, (200, 190, 255)); s.sfx('kill', .6)
                else: m.stun = 4.0; s.burst(m.x, m.y - 10, 6, WHITE)
        R = s.R
        if R['goal'] == 'village' and not s.door_open and math.hypot(p.x - R['door'], (p.y - 122) * 1.2) < 70:
            s.door_open = True; s.sfx('open'); s.say(R['openmsg'], 3.0); s.burst(R['door'], 90, 26, (200, 230, 255), 70); s.shake = .4
        b = s.boss
        if b and b['state'] == 'glow' and math.hypot(p.x - s.R['bellx'], (p.y - 150) * 1.3) < 80:
            b['hp'] -= 1; b['t'] = 0.0; s.shake = .8; s.flash = .7; s.fcol = (255, 240, 200); s.sfx('thump'); s.burst(s.R['bellx'], 120, 30, GOLD, 90)
            if b['hp'] <= 0: b['state'] = 'won'; s.won_t = 0.0; s.sfx('bell'); s.say('THE BELL IS FREE...', 4.0)
            else: b['state'] = 'stagger'; s.say('IT CRACKS! %d MORE!' % b['hp'], 2.5)
    # ---------------- update
    def update(s, dt):
        s.t += dt; s.read_inputs(); ev = s.ev; s.ev = []
        if s.sound and not s.music_on and 'snd' in MUSIC:
            try: MUSIC['snd'].set_volume(.5 * s.volume); MUSIC['snd'].play(-1); s.music_on = True
            except Exception: pass
        s.shake = max(0.0, s.shake - dt); s.flash = max(0.0, s.flash - dt * 1.6); s.msg_t = max(0.0, s.msg_t - dt); s.banner_t = max(0.0, s.banner_t - dt)
        if s.fade_dir > 0:
            s.fade = min(1.0, s.fade + dt * 2.4)
            if s.fade >= 1.0:
                act = s.fade_act; s.fade_act = None; s.fade_dir = -1
                if act: act()
        elif s.fade_dir < 0 and s.fade > 0: s.fade = max(0.0, s.fade - dt * 2.0)
        if s.R.get('snow'):
            for q in s.snow: q[1] += q[2] * dt; q[0] += (math.sin(s.t + q[3]) * 8 + 8) * dt; q[0] %= W; q[1] %= H
        for q in s.parts: q[0] += q[2] * dt; q[1] += q[3] * dt; q[3] += 60 * dt; q[4] -= dt
        s.parts = [q for q in s.parts if q[4] > 0]
        st = s.state
        if st == 'title': s.up_title(ev)
        elif st == 'comic': s.up_comic(dt, ev)
        elif st == 'play': s.up_play(dt, ev)
        elif st == 'trial': s.up_trial(dt, ev)
        elif st == 'pause': s.up_pause(ev)
        elif st == 'settings': s.up_settings(ev)
        elif st == 'dead':
            s.dead_t += dt
            for e in ev:
                if s.dead_t > .8 and (e[0] == 'tap' or (e[0] == 'key' and e[1] in ('act', 'light'))): s.fade_to(s.begin_trial if s.dead_to == 'trial' else s.respawn); break
    def menu_items(s):
        items = ['START']
        if s.save.get('room', 0) > 0: items.append('CONTINUE')
        items.extend(['SETTINGS', 'SOUND: ON' if s.sound else 'SOUND: OFF'])
        return items
    def menu_rect(s, i): return (100, 91 + i * 19, 120, 16)
    def up_title(s, ev):
        items = s.menu_items()
        for e in ev:
            act = None
            if e[0] == 'key':
                if e[1] == 'up': s.sel = (s.sel - 1) % len(items)
                elif e[1] == 'down': s.sel = (s.sel + 1) % len(items)
                elif e[1] == 'act': act = s.sel
            elif e[0] == 'tap':
                for i in range(len(items)):
                    r = s.menu_rect(i)
                    if r[0] - 6 <= e[1] <= r[0] + r[2] + 6 and r[1] - 2 <= e[2] <= r[1] + r[3] + 2: act = i; s.sel = i
            if act is not None:
                s.sfx('blip'); lab = items[act]
                if lab == 'START': s.fade_to(s.new_game)
                elif lab == 'CONTINUE': s.fade_to(lambda: s.start_room(clamp(s.save.get('room', 0), 0, len(ROOMS) - 1), True))
                elif lab == 'SETTINGS': s.settings_from = 'title'; s.settings_sel = 0; s.state = 'settings'
                else: s.toggle_sound()
                return
    def toggle_sound(s):
        s.sound = not s.sound
        if not s.sound:
            try: pygame.mixer.stop()
            except Exception: pass
        else: s.music_on = False
    def settings_action(s, index):
        if index == 0: s.volume = max(0.0, round(s.volume - 0.1, 2))
        elif index == 1: s.volume = min(1.0, round(s.volume + 0.1, 2))
        if index in (0, 1):
            try:
                if 'snd' in MUSIC: MUSIC['snd'].set_volume(.5 * s.volume)
            except Exception: pass
        elif index == 2:
            global LANGUAGE
            LANGUAGE = 'fa' if LANGUAGE == 'en' else 'en'
            _tc.clear(); _fc.clear(); _fh.clear(); _hc.clear(); _sc.clear(); del _tq[:]
        else: s.state = s.settings_from
    def up_settings(s, ev):
        for e in ev:
            if e[0] == 'key':
                if e[1] == 'back': s.state = s.settings_from; return
                if e[1] == 'up': s.settings_sel = (s.settings_sel - 1) % 4
                elif e[1] == 'down': s.settings_sel = (s.settings_sel + 1) % 4
                elif e[1] == 'act': s.settings_action(s.settings_sel); return
            elif e[0] == 'tap':
                x, y = e[1], e[2]
                if 80 <= x <= 150 and 77 <= y <= 101: s.settings_action(0); return
                if 170 <= x <= 240 and 77 <= y <= 101: s.settings_action(1); return
                if 65 <= x <= 255 and 108 <= y <= 132: s.settings_action(2); return
                if 90 <= x <= 230 and 139 <= y <= 163: s.settings_action(3); return
    def up_comic(s, dt, ev):
        s.ct += dt; cap = s.comic[s.ci][1][1]; total = len(cap)
        if int((s.ct - .5) * 36) > s.lastblip and int((s.ct - .5) * 36) < total and int((s.ct - .5) * 36) % 3 == 0: s.sfx(VOICES.get(s.comic[s.ci][1][0], 'blip'), .5)
        s.lastblip = int((s.ct - .5) * 36)
        for e in ev:
            if (e[0] == 'tap' and e[2] < 14 and e[1] > 270) or (e[0] == 'key' and e[1] == 'back'): s.end_comic(); return
            if e[0] == 'tap' or (e[0] == 'key' and e[1] in ('act', 'light')):
                if int((s.ct - .5) * 36) < total: s.ct = .5 + total / 36.0 + .02
                elif s.ci + 1 < len(s.comic): s.ci += 1; s.ct = 0.0; s.sfx('click' if 'click' in SFX else 'blip')
                else: s.end_comic()
                return
    def up_pause(s, ev):
        for e in ev:
            if e[0] == 'key' and e[1] == 'back': s.state = s.pause_to; return
            if e[0] == 'tap':
                for i in range(4):
                    r = (100, 72 + i * 22, 120, 18)
                    if r[0] <= e[1] <= r[0] + r[2] and r[1] <= e[2] <= r[1] + r[3]:
                        if i == 0: s.state = s.pause_to
                        elif i == 1: s.settings_from = 'pause'; s.settings_sel = 0; s.state = 'settings'
                        elif i == 2: s.toggle_sound()
                        else: s.to_title()
                        return
    def blocked(s, x, y):
        for ox, oy, ow, oh in s.obst:
            if x - 4 < ox + ow and x + 4 > ox and y - 2 < oy + oh and y + 2 > oy: return True
        return False
    def targets(s):
        R = s.R; out = []
        for n in R['notes']: out.append(('note', n[0], n[1], n))
        for st in s.stones: out.append(('stone', st['x'], st['y'], st))
        for c in s.candles: out.append(('candle', c['x'], c['y'], c))
        if R.get('npc'): out.append(('npc', R['npc']['x'], R['npc']['y'], None))
        if s.halls:
            out.append(('note', 60, 126, (60, 126, 'WALL SCRATCHES', s.halls['clue'])))
            for i, hx in enumerate(R['hdoors']): out.append(('hdoor', hx, 122, i))
        if R['door']: out.append(('door', R['door'], 122, None))
        return out
    def near_target(s):
        p = s.p; best = None; bd = 9e9
        for t in s.targets():
            dx = abs(p.x - t[1]); dy = abs(p.y - t[2])
            ok = (dx < 30 and p.y < 142) if t[0] in ('door', 'hdoor') else (dx < 26 and dy < 22)
            if ok and dx + dy < bd: best, bd = t, dx + dy
        return best
    def use(s, t):
        k = t[0]; R = s.R; p = s.p
        if k == 'note': s.sfx('blip'); s.talk([('NOTE', l) for l in t[3][3]])
        elif k == 'stone':
            st = t[3]
            if st['lit']: return
            if st['k'] == R['order'][s.next_stone]:
                st['lit'] = True; s.sfx('rune%d' % min(2, s.next_stone)); s.next_stone += 1; s.burst(st['x'], st['y'] - 14, 14, GOLD)
                if s.next_stone >= len(R['order']):
                    s.door_open = True; s.sfx('open'); s.say(R['openmsg'], 3.5); s.shake = .6
                    if R.get('solved'): s.talk(R['solved'])
                elif R.get('whisper'): s.say(R['whisper'].get(st['k'], ''), 3.0)
            else:
                for q in s.stones: q['lit'] = False
                s.next_stone = 0; s.sfx('wrong'); s.say('THE SPIRITS TURN THEIR BACKS. THE DARK STIRS...' if R['goal'] == 'runes' else 'WRONG. THE DARK STIRS...', 2.8); s.flash = .3; s.fcol = (120, 30, 60); s.spawn_shadow()
        elif k == 'candle':
            c = t[3]
            if c['lit']: return
            c['lit'] = True; s.sfx('lamp'); s.burst(c['x'], c['y'] - 18, 10, GOLD)
            if all(q['lit'] for q in s.candles): s.door_open = True; s.sfx('open'); s.say(R['openmsg'], 3.5)
            else:
                s.spawn_shadow(); s.say('SOMETHING WAKES IN THE DARK...', 2.4)
        elif k == 'npc':
            if s.has_heart: s.talk(R['repeat'])
            else: s.talk(R['talk1'], lambda: s.give_heart(s.after_heart))
        elif k == 'hdoor': s.use_hdoor(t[3])
        elif k == 'fstation': s.fun_station(t[3])
        elif k == 'fhide': s.fun_hide(t[3])
        elif k == 'fexit': s.use(('door', 0, 0, None))
        elif k == 'door':
            if s.door_open:
                s.sfx('open'); nxt = R.get('after')
                if nxt: s.fade_to(lambda: s.begin_comic(nxt, lambda: s.start_room(s.ri + 1, True)))
                else: s.fade_to(lambda: s.start_room(s.ri + 1, True))
            else: s.sfx('wrong'); s.say(R['locked'], 3.0)
    def give_heart(s, cb):
        s.has_heart = True; s.p.maxhp = 4; s.p.hp = 4; s.item_t = 3.4; s.item_cb = cb; s.sfx('open'); s.sfx('thump'); s.flash = .8; s.fcol = (255, 60, 90); s.shake = .5
        s.burst(s.R['npc']['x'], s.R['npc']['y'] - 20, 24, (255, 90, 120), 70)
    def after_heart(s):
        s.door_open = True; s.say(s.R['openmsg'], 3.5); s.talk(s.R['talk2'])
    def up_play(s, dt, ev):
        p = s.p; R = s.R; w = R['w']
        if s.item_t > 0:
            s.item_t -= dt
            if s.item_t <= 0:
                cb = s.item_cb; s.item_cb = None
                if cb: cb()
            return
        if s.scare_t > 0:                                # the lights die, and Dean is suddenly right in front of Mira
            a_ = s.scare_t; s.scare_t -= dt; b_ = s.scare_t; D = s.dean
            if a_ > 3.0 >= b_: s.sfx('creak')
            if a_ > 2.0 >= b_: s.sfx('whisper')
            if a_ > 1.2 >= b_:
                D['state'] = 'idle'; D['a'] = 1.0; s.obst.append((D['x'] - 9, D['y'] - 4, 18, 8)); s.sfx('scare'); s.sfx('glitch'); s.flash = 1.0; s.fcol = (255, 255, 255); s.shake = .9
                s.burst(D['x'], D['y'] - 24, 20, (230, 40, 70), 80)
            if b_ <= 0: s.scare_t = 0.0; s.talk(R['dean_talk'], s.go_trial)
            return
        if s.strike_t > 0:                               # Dean tears out one heart, then folds out of the world
            a_ = s.strike_t; s.strike_t -= dt; b_ = s.strike_t; D = s.dean
            if a_ > 2.2 >= b_: D['state'] = 'idle'; s.sfx('scare'); s.sfx('glitch')
            if a_ > 1.6 >= b_:
                D['x'] = p.x + 20; s.sfx('hurt'); s.flash = 1.0; s.fcol = (220, 20, 50); s.shake = 1.0; s.burst(p.x, p.y - 14, 26, RED, 95)
                if not s.save.get('dl'): p.maxhp = max(1, p.maxhp - 1)
                s.save['dl'] = 1; write_save(s.save); p.hp = p.maxhp; s.say('HE TORE A HEART OUT OF YOU. MAX HEARTS -1', 3.4)
            if b_ < 1.6:
                D['a'] = max(0.0, b_ / 1.6)
                if random.random() < .8: s.burst(D['x'], D['y'] - 24, 2, (230, 70, 90), 45)
            if a_ > .5 >= b_: s.sfx('glitch')
            if b_ <= 0:
                s.strike_t = 0.0; D['state'] = 'gone'; s.door_open = True; s.sfx('open'); s.talk(R['dean_end'], s.after_dean)
            return
        if s.hb_t > 0:                                   # Mira's heart burns Dean away for good
            s.hb_t -= dt; k = 1 - max(0.0, s.hb_t) / 4.2; D = s.dean; s.shake = .22
            if int(s.t * 6) != int((s.t - dt) * 6): s.sfx('thump', .4)
            if s.dean and k > .3:
                s.dean['a'] = max(0.0, 1.0 - (k - .3) / .6)
                if random.random() < .7: s.burst(D['x'], D['y'] - 24, 2, (230, 70, 90), 45)
            if s.hb_t <= 0:
                s.hb_t = 0.0
                if s.dean: s.dean['state'] = 'dead'
                s.door_open = True; s.sfx('open'); s.flash = 1.0; s.fcol = (255, 240, 220); s.shake = .6
                s.talk(R['dean_end'], s.after_dean)
            return
        # dialogue takes over
        if s.dlg:
            spk, txt = s.dlg[s.di] if s.dlg[s.di][0] != '?' else ('', '')
            if not s.choice and s.dch < len(txt):
                s.dch = min(float(len(txt)), s.dch + dt * 38)
                if int(s.dch) % 3 == 0 and int(s.dch) != s.lastblip: s.lastblip = int(s.dch); s.sfx(VOICES.get(spk, 'blip'), .5)
            for e in ev:
                if s.choice:
                    if e[0] == 'key' and e[1] in ('up', 'down'): s.csel = (s.csel + 1) % len(s.choice)
                    elif e[0] == 'key' and e[1] == 'act': s.pick(s.csel); break
                    elif e[0] == 'tap':
                        for i in range(len(s.choice)):
                            if 30 <= e[1] <= 290 and 66 + i * 26 <= e[2] <= 66 + i * 26 + 22: s.pick(i); break
                        break
                elif e[0] == 'tap' or (e[0] == 'key' and e[1] in ('act', 'light')): s.adv_talk(); break
            return
        if R.get('fun'): s.up_fun(dt, ev); return
        if R.get('home'): s.up_home(dt, ev); return
        if R.get('td'): s.up_td(dt, ev); return
        for e in ev:
            if e[0] == 'key' and e[1] == 'back': s.pause_to = 'play'; s.state = 'pause'; return
            if e[0] == 'tap' and e[1] > 296 and e[2] < 20: s.pause_to = 'play'; s.state = 'pause'; return
            if e[0] == 'key' and e[1] == 'act' and s.won_t == 0.0:
                t = s.near_target()
                if t: s.use(t)
            if e[0] == 'key' and e[1] == 'light' and p.energy >= 30 and s.pulse_t <= 0 and s.won_t == 0.0: s.do_pulse()
        if s.state != 'play' or s.dlg: return
        # movement
        mx, my = s.mv; p.moving = math.hypot(mx, my) > .1
        nx = clamp(p.x + (mx * SPEED + p.kx) * dt, 10, w - 10); ny = clamp(p.y + (my * SPEED * .85 + p.ky) * dt, FY0, FY1)
        if not s.blocked(nx, p.y): p.x = nx
        if not s.blocked(p.x, ny): p.y = ny
        p.kx *= max(0.0, 1 - dt * 8); p.ky *= max(0.0, 1 - dt * 8)
        if p.moving:
            if abs(mx) >= abs(my) * .9: p.dir = 'r' if mx > 0 else 'l'
            else: p.dir = 'u' if my < 0 else 'd'
            p.anim += dt * 8; p.stepT -= dt
            if p.stepT <= 0: p.stepT = .3; s.sfx('step', .35)
        else: p.anim = 0.0
        p.inv = max(0.0, p.inv - dt); s.pulse_t = max(0.0, s.pulse_t - dt)
        p.energy = min(100.0, p.energy + dt * (14 + (6 if s.has_heart else 0) + (10 if any(c['lit'] and abs(c['x'] - p.x) < 60 for c in s.candles) else 0)))
        for m in s.mons:
            m.update(dt, p, w)
            if m.alive and m.stun <= 0 and abs(m.x - p.x) < 9 and abs(m.y - p.y) < 6: s.hurt(m)
        s.mons = [m for m in s.mons if m.alive or m.dying > 0]
        if s.dean and s.dean['state'] == 'hidden' and p.x > R.get('scare_x', 300):
            s.scare_t = 3.6; p.moving = False; p.anim = 0.0; s.dean['x'] = clamp(p.x + 64, 60, w - 70)
        if s.halls:
            s.buzz_t -= dt
            if s.buzz_t <= 0: s.buzz_t = .5; s.sfx('buzz', .3)
        if s.boss: s.up_boss(dt)
        s.cam += (clamp(p.x - W * .45, 0, w - W) - s.cam) * min(1.0, dt * 6)
    def up_boss(s, dt):
        b = s.boss; b['t'] += dt; alive = [m for m in s.mons if m.alive]
        if b['state'] == 'wave':
            b['spawn'] -= dt
            if b['spawn'] <= 0 and len(alive) < 3 + (3 - b['hp']): s.spawn_shadow(); b['spawn'] = 2.4
            if b['t'] > 6.5: b['state'] = 'glow'; b['t'] = 0.0; s.sfx('creak'); s.say('THE CORE GLOWS! GET CLOSE AND PRESS LIGHT!', 3.0)
        elif b['state'] == 'glow':
            if b['t'] > 3.6: b['state'] = 'wave'; b['t'] = 0.0; s.say('IT RECOVERS...', 1.8)
        elif b['state'] == 'stagger':
            if b['t'] > 1.6: b['state'] = 'wave'; b['t'] = 0.0
        elif b['state'] == 'won':
            s.won_t += dt
            for m in s.mons: m.alive = False; m.dying = 0.0
            if s.won_t > 2.6 and s.fade_dir <= 0:
                s.save['done'] = True; s.save['room'] = 0; write_save(s.save)
                s.fade_to(lambda: s.begin_comic(ENDING, s.to_title))

    def tnames(s): return TRIAL_NAMES2 if s.trial_hard else TRIAL_NAMES
    def dean_strike(s): s.strike_t = 3.0
    def after_dean(s):
        R = s.R
        if R.get('final'):                               # the stolen heart comes home
            s.save['dl'] = 0; write_save(s.save); s.p.maxhp = 4; s.p.hp = 4; s.sfx('lamp'); s.burst(s.p.x, s.p.y - 14, 24, (255, 90, 120), 80); s.flash = .6; s.fcol = (255, 60, 90)
        s.say(R['openmsg'], 3.5)
    # ---------------- the Yellow Halls (Backrooms level 1): rooms inside rooms, find the true door three times
    def halls_round(s, r):
        R = s.R; n = len(R['hdoors']); correct = random.randrange(n); colors = [(150, 122, 60)] * n; flick = [False] * n; marks = [random.randint(0, 3) for _ in range(n)]
        if r == 1:
            flick = [i != correct for i in range(n)]; clue = ['THE HALL LIES. BUT A LIGHT CANNOT.', 'TAKE THE DOOR UNDER THE LIGHT THAT DOES NOT FLICKER.']
        elif r == 2:
            marks = [1, 2, 3, 4]; random.shuffle(marks); correct = marks.index(1); clue = ['THE FALSE DOORS WERE KNOCKED ON MANY TIMES.', 'TAKE THE DOOR WITH THE FEWEST SCRATCHES.']
        else:
            colors[correct] = (104, 134, 84); clue = ['THE EXIT IS NEVER THE SAME COLOR AS THE REST.', 'THE HALL HAS NOTICED YOU. HURRY.']
        s.halls = {'round': r, 'correct': correct, 'colors': colors, 'flick': flick, 'marks': marks, 'clue': clue}
    def hlight(s, i):
        H_ = s.halls
        return (not H_['flick'][i]) or ((math.sin(s.t * 37 + i * 5) + math.sin(s.t * 23 + i * 2)) > -.3)
    def use_hdoor(s, i):
        H_ = s.halls; R = s.R; p = s.p
        if i == H_['correct']:
            s.sfx('open'); s.burst(R['hdoors'][i], 90, 16, (255, 240, 170), 60)
            if H_['round'] >= 3: s.door_open = True; s.say(R['openmsg'], 3.5); s.flash = .5; s.fcol = (180, 255, 190); s.shake = .4
            else: s.fade_to(s.halls_next)
        else:
            s.sfx('wrong'); s.sfx('scare', .6); s.flash = .6; s.fcol = (150, 120, 30); s.shake = .6; s.halls_round(H_['round'])
            p.x = float(R['spawn'][0]); p.y = float(R['spawn'][1]); p.kx = p.ky = 0.0; s.cam = 0.0
            if sum(1 for m in s.mons if m.alive) < 6: s.spawn_shadow(); s.spawn_shadow()
            s.say('WRONG DOOR. THE HALL LOOPS YOU BACK...', 3.0)
    def halls_next(s):
        r = s.halls['round'] + 1; s.halls_round(r); p = s.p; p.x = float(s.R['spawn'][0]); p.y = float(s.R['spawn'][1]); p.kx = p.ky = 0.0; s.cam = 0.0
        s.mons = [m for m in s.mons if m.alive][:3]; s.say('THE TRUE DOOR. THE HALL SHIFTS DEEPER...', 3.0); s.sfx('creak')
        if r == 3: s.spawn_shadow(); s.spawn_shadow()
    def draw_hdoors(s, cx):
        H_ = s.halls; R = s.R; ex = R['door'] - cx
        if -30 < ex < W + 30:
            rect(frame, (10, 40, 24), ex - 17, 36, 34, 13); rect(frame, (40, 130, 80), ex - 16, 37, 32, 11)
            text(frame, 'EXIT', ex, 38, (190, 255, 205), 10, 'c', False)
        if H_['round'] >= 1:
            nx = 60 - cx
            if -20 < nx < W + 20: rect(frame, (230, 224, 206), nx - 5, 80, 10, 13); rect(frame, (110, 100, 90), nx - 3, 83, 6, 1); rect(frame, (110, 100, 90), nx - 3, 86, 6, 1)
        for i, hx in enumerate(R['hdoors']):
            x = hx - cx
            if x < -30 or x > W + 30: continue
            col = H_['colors'][i]; dk = mixc(col, (0, 0, 0), .45); top = 50; bot = WALL_B - 4
            rect(frame, dk, x - 15, top - 2, 30, bot - top + 2); rect(frame, col, x - 13, top, 26, bot - top)
            rect(frame, dk, x - 13, top + 10, 26, 1); rect(frame, dk, x - 13, top + 30, 26, 1); rect(frame, (200, 180, 90), x + 8, bot - 28, 3, 3)
            for m in range(H_['marks'][i]): pygame.draw.line(frame, dk, (x - 9 + m * 4, top + 14), (x - 9 + m * 4, top + 24), 1)
            rect(frame, (250, 250, 214) if s.hlight(i) else (120, 112, 76), x - 14, 22, 28, 4)
    # ---------------- LEVEL FUN (Backrooms "Level Fun"): a top-down party maze. Only Partygoers live here.
    def fun_init(s):
        D_ = fun_data(); p = s.p
        s.fun = {'D': D_, 'G': D_['G'], 'step': 0, 'done': set(), 'hat': False, 'music': False, 'cake': False, 'pgs': [], 'flow': None, 'flow_t': 0.0, 'aflow': None,
                 'hid': None, 'hide_t': 0.0, 'tip': False, 'honk': -9.0, 'amb_t': 3.0, 'area': -1, 'area_t': 0.0, 'ptile': None, 'seen': [[False] * FGW for _ in range(FGH)], 'mm': pygame.Surface((FGW, FGH), pygame.SRCALPHA)}
        F = s.fun
        for tx, ty, rad, kind in FPG: F['pgs'].append(Partygoer(tx * FTS + 8, ty * FTS + 8, rad, kind))
        t = [('note', n[0] * FTS + 8, n[1] * FTS + 8, (n[0] * FTS + 8, n[1] * FTS + 8, n[2], n[3])) for n in FNOTES]
        t += [('fstation', o['cx'], o['cy'], o) for o in D_['stations']]; t += [('fhide', o['cx'], o['cy'], o) for o in D_['hides']]; t.append(('fexit', FEXIT[0], FEXIT[1], None)); F['targets'] = t; s.kill_kind = None
        s.cam = clamp(p.x - W * .5, 0, FGW * FTS - W); s.camy = clamp(p.y - H * .5, 0, FGH * FTS - H)
        s.fconf = [[random.uniform(0, W), random.uniform(0, H), random.uniform(-6, 6), random.uniform(12, 34), random.choice(BAL_COLS)] for _ in range(46)]
        s.fun_see()
    def fun_see(s):                                                      # fills in the little map as Mira explores
        F = s.fun; p = s.p; tx = int(p.x // FTS); ty = int(p.y // FTS)
        if F['ptile'] == (tx, ty): return
        F['ptile'] = (tx, ty); G = F['G']; seen = F['seen']; mm = F['mm']
        for yy in range(max(0, ty - 5), min(FGH, ty + 6)):
            for xx in range(max(0, tx - 6), min(FGW, tx + 7)):
                if not seen[yy][xx] and G[yy][xx] != 1 and (xx - tx) ** 2 + (yy - ty) ** 2 <= 30: seen[yy][xx] = True; mm.set_at((xx, yy), (226, 214, 246, 220))
        r = F['D']['rid'][ty][tx]
        if r != F['area']:
            F['area'] = r
            if r >= 0: F['area_t'] = 2.4
    def fun_near(s):
        p = s.p; best = None; bd = 9e9
        for t in s.fun['targets']:
            d = math.hypot(p.x - t[1], p.y - t[2]); r = 22 if t[0] == 'note' else (34 if t[0] in ('fstation', 'fhide') else 30)
            if d < r and d < bd: best, bd = t, d
        return best
    def fun_station(s, st):
        F = s.fun; R = s.R; k = st['key']
        if k in F['done']: s.say('THIS STEP IS ALREADY DONE.', 2.0); return
        if k == R['order'][F['step']]:
            F['done'].add(k); F['step'] += 1; s.burst(st['cx'], st['cy'] - 16, 18, random.choice(BAL_COLS), 70)
            if k == 'hats': F['hat'] = True; s.sfx('lamp'); s.sfx('pop', .6); s.say('YOU PUT ON A PAPER HAT. THE PARTYGOERS WATCH YOU LESS CLOSELY.', 3.6)
            elif k == 'music': F['music'] = True; s.sfx('mbox'); s.say('THE MUSIC BOX PLAYS. THE LIGHTS START TO DANCE.', 3.6)
            elif k == 'cake': F['cake'] = True; s.sfx('lamp'); s.say('THE CANDLES CATCH LIGHT, ONE BY ONE.', 3.6)
            else:
                s.door_open = True; s.sfx('open'); s.sfx('pop'); s.shake = .5; s.flash = .5; s.fcol = (180, 255, 190); s.say(R['openmsg'], 3.6)
                for _ in range(3): s.burst(st['cx'] + random.randint(-12, 12), st['cy'] - 14, 20, random.choice(BAL_COLS), 90)
                s.talk(R['solved'])
        else:                                                            # wrong order: the whole party starts walking towards you
            F['done'] = set(); F['step'] = 0; F['hat'] = False; F['music'] = False; F['cake'] = False
            s.sfx('horn'); s.sfx('scare', .6); s.flash = .6; s.fcol = (255, 90, 160); s.shake = .5
            s.say('WRONG ORDER! A PARTY HORN SCREAMS. THE PARTYGOERS TURN THEIR HEADS...', 3.8)
            F['aflow'] = fun_flow(F['G'], int(s.p.x // FTS), int(s.p.y // FTS))
            for m in F['pgs']: m.mode = 'alert'; m.alert = 9.0; m.stun = 0.0; m.path = []
    def fun_hide(s, o):                                                  # crawl into the closet under a table
        F = s.fun; p = s.p
        if F['hid']: return
        for m in F['pgs']:
            if m.mode == 'chase' and math.hypot(m.x - p.x, m.y - p.y) < 16: s.say('TOO LATE! IT IS RIGHT BEHIND YOU.', 2.2); return
        F['hid'] = o; F['hide_t'] = 0.0; F['flow_t'] = 0.0
        p.x = o['fx']; p.y = o['fy']; p.kx = p.ky = 0.0; p.moving = False; p.dir = 'u'
        seen = False
        for m in F['pgs']:
            if m.mode == 'chase' and fun_los(F['G'], m.x, m.y, p.x, p.y) and math.hypot(m.x - p.x, m.y - p.y) < 110:
                m.mode = 'check'; m.path = []; m.ct = 2.6; seen = True        # it watched you crawl in: it will come and open the closet
            elif m.mode in ('chase', 'alert'):
                m.mode = 'wander'; m.path = []; m.wait = 1.5; m.lost = 0.0    # it lost you
        s.sfx('creak', .5)
        s.say('IT SAW YOU HIDE. IT IS COMING TO CHECK...' if seen else 'YOU SLIP INTO THE CLOSET UNDER THE TABLE. HOLD YOUR BREATH.', 3.2)
    def fun_unhide(s):
        F = s.fun; F['hid'] = None; F['hide_t'] = 0.0; s.sfx('creak', .4)
    def fun_kill(s, m):                                                  # a Partygoer found Mira: she dies at once
        p = s.p; F = s.fun; F['hid'] = None; p.hp = 0; s.kill_kind = m.kind
        s.sfx('scare'); s.sfx('horn'); s.shake = 1.0; s.flash = 1.0; s.fcol = (255, 214, 40); s.burst(p.x, p.y - 12, 16, RED, 80)
        s.dead_to = None; s.state = 'dead'; s.dead_t = 0.0
    def fun_pulse(s):
        p = s.p; F = s.fun; p.energy -= 30; s.pulse_t = .4; s.sfx('pulse')
        for m in F['pgs']:
            if math.hypot(m.x - p.x, m.y - p.y) < 62:
                m.stun = 4.0; m.mode = 'wander'; m.path = []; m.lost = 0.0; m.wait = 2.0; s.burst(m.x, m.y - 14, 10, random.choice(BAL_COLS), 55); s.sfx('pop', .5)
    def fun_pg_update(s, dt):
        F = s.fun; p = s.p; G = F['G']; slowset = F['D']['slow']; hat = F['hat']; hid = F['hid']
        F['flow_t'] -= dt
        if F['flow_t'] <= 0 or F['flow'] is None: F['flow_t'] = .3; F['flow'] = fun_flow(G, int(p.x // FTS), int(p.y // FTS))
        for m in F['pgs']:
            m.t += dt; ox = m.x; oy = m.y
            if m.stun > 0: m.stun -= dt; m.mv = False; continue
            d = math.hypot(p.x - m.x, p.y - m.y)
            see = (not hid) and (d < 30 or (d < (84 if hat else 118) and fun_los(G, m.x, m.y, p.x, p.y)))
            slow = .65 if (int(m.x // FTS), int(m.y // FTS)) in slowset else 1.0
            if see:
                if m.mode != 'chase':
                    m.mode = 'chase'; m.path = []
                    if s.t - F['honk'] > 1.6: F['honk'] = s.t; s.sfx('horn', .4)
                    if not F['tip']: F['tip'] = True; s.say('RUN! HIDE IN A CLOSET UNDER A TABLE. IF THEY CATCH YOU, YOU DIE.', 4.2)
                m.lost = 0.0
            if m.mode == 'check':                                        # it saw Mira crawl into a closet: it walks over, waits, then opens the door
                if not hid: m.mode = 'wander'; m.path = []; m.wait = 1.0
                elif d > 14:
                    nx = fun_next(F['flow'], m.x, m.y, p.x, p.y)
                    if nx: fun_move(G, m, nx[0], nx[1], 30.0 * slow, dt)
                else:
                    m.ct -= dt
                    if m.ct <= 0: s.fun_kill(m); return
            elif m.mode == 'chase':
                if not see:
                    m.lost += dt
                    if m.lost > 4.0: m.mode = 'wander'; m.path = []; m.wait = 1.0
                if m.mode == 'chase':
                    nx = fun_next(F['flow'], m.x, m.y, p.x, p.y)
                    if nx: fun_move(G, m, nx[0], nx[1], 40.0 * slow, dt)
            elif m.mode == 'alert':
                m.alert -= dt; nx = fun_next(F['aflow'], m.x, m.y)
                if nx is None or m.alert <= 0: m.mode = 'wander'; m.path = []; m.wait = 1.0
                else: fun_move(G, m, nx[0], nx[1], 34.0 * slow, dt)
            else:
                m.wait -= dt
                if not m.path:
                    if m.wait <= 0:
                        for _ in range(8):
                            gx = int(m.hx // FTS) + random.randint(-m.rad, m.rad); gy = int(m.hy // FTS) + random.randint(-m.rad, m.rad)
                            if 0 <= gx < FGW and 0 <= gy < FGH and not G[gy][gx]:
                                m.path = fun_path(G, int(m.x // FTS), int(m.y // FTS), gx, gy)
                                if m.path: break
                        m.wait = random.uniform(.3, 1.6)
                else:
                    cxp = m.path[0][0] * FTS + 8; cyp = m.path[0][1] * FTS + 8; fun_move(G, m, cxp, cyp, 24.0 * slow, dt)
                    if math.hypot(cxp - m.x, cyp - m.y) < 3: m.path.pop(0)
            m.mv = abs(m.x - ox) + abs(m.y - oy) > .02
            if m.path and not m.mv:
                m.stuck += dt
                if m.stuck > 1.5: m.path = []; m.stuck = 0.0
            else: m.stuck = 0.0
            if (not hid) and abs(m.x - p.x) < 10 and abs(m.y - p.y) < 8: s.fun_kill(m); return      # one touch and Mira is gone
    def up_fun(s, dt, ev):
        p = s.p; F = s.fun; G = F['G']
        for e in ev:
            if e[0] == 'key' and e[1] == 'back': s.pause_to = 'play'; s.state = 'pause'; return
            if e[0] == 'tap' and e[1] > 296 and e[2] < 20: s.pause_to = 'play'; s.state = 'pause'; return
            if e[0] == 'key' and e[1] == 'act':
                if F['hid']:
                    if F['hide_t'] > .35: s.fun_unhide()
                else:
                    t = s.fun_near()
                    if t: s.use(t)
        if s.state != 'play' or s.dlg: return
        for q in s.fconf:
            q[0] = (q[0] + q[2] * dt) % W; q[1] += q[3] * dt
            if q[1] > H: q[1] -= H + 4
        F['area_t'] = max(0.0, F['area_t'] - dt); F['amb_t'] -= dt
        if F['amb_t'] <= 0: F['amb_t'] = random.uniform(8, 13); s.sfx('mbox', .5 if F['music'] else .18)
        mx, my = s.mv
        if F['hid']:                                                     # crouched in the closet: no walking, just waiting
            F['hide_t'] += dt; p.moving = False; p.anim = 0.0
            if F['hide_t'] > .6 and math.hypot(mx, my) > .6: s.fun_unhide()
        else:
            p.moving = math.hypot(mx, my) > .1
            sp = SPEED * (.62 if (int(p.x // FTS), int(p.y // FTS)) in F['D']['slow'] else 1.0)
            nx = p.x + (mx * sp + p.kx) * dt; ny = p.y + (my * sp + p.ky) * dt
            if not fun_blocked(G, nx, p.y): p.x = nx
            if not fun_blocked(G, p.x, ny): p.y = ny
            p.kx *= max(0.0, 1 - dt * 8); p.ky *= max(0.0, 1 - dt * 8)
            if p.moving:
                if abs(mx) >= abs(my) * .9: p.dir = 'r' if mx > 0 else 'l'
                else: p.dir = 'u' if my < 0 else 'd'
                p.anim += dt * 8; p.stepT -= dt
                if p.stepT <= 0: p.stepT = .3; s.sfx('step', .35)
            else: p.anim = 0.0
        p.inv = max(0.0, p.inv - dt); s.pulse_t = max(0.0, s.pulse_t - dt); p.energy = min(100.0, p.energy + dt * 20)
        s.fun_see(); s.fun_pg_update(dt)
        s.cam += (clamp(p.x - W * .5, 0, FGW * FTS - W) - s.cam) * min(1.0, dt * 6); s.camy += (clamp(p.y - H * .5 + 8, 0, FGH * FTS - H) - s.camy) * min(1.0, dt * 6)
    def fun_lights(s, cx, cy):
        p = s.p; F = s.fun; L = []
        lx, ly = s.lantern_pos(); fl = int(math.sin(s.t * 9) * 2 + math.sin(s.t * 13)); low = 2 if p.hp == 1 else 0
        L.append((p.x - cx, p.y - 10 - cy, 8 if F['hid'] else 30, (150, 140, 124)))                    # no lantern in here: only a faint glow around Mira
        for m in F['pgs']: L.append((m.x - cx, m.y - 24 - cy, 34 if m.mode in ('chase', 'check') else 22, (120, 96, 12)))
        sp = 3.0 if F['music'] else .8
        for i, (nm, x, y, w, h, st) in enumerate(FROOMS): L.append(((x + w / 2.0) * FTS - cx, (y + h / 2.0) * FTS - cy, 84, DISCO[(int(s.t * sp) + i) % len(DISCO)]))
        for (x, y, w, h) in FCORR: L.append(((x + w / 2.0) * FTS - cx, (y + h / 2.0) * FTS - cy, 44, (255, 236, 190)))
        for o in F['D']['stations']:
            if o['key'] in F['done']: L.append((o['cx'] - cx, o['cy'] - 10 - cy, 30, (255, 226, 150)))
        if s.door_open: L.append((FEXIT[0] - cx, FEXIT[1] - 8 - cy, 54, (140, 255, 170)))
        return L
    def draw_fexit(s, cx, cy):
        x = FEXIT_T[0] * FTS - cx; y = FEXIT_T[1] * FTS - cy
        if x < -40 or x > W + 8: return
        rect(frame, (14, 40, 26), x - 1, y - 12, 34, 30)
        if s.door_open:
            rect(frame, (40, 150, 90), x + 1, y - 10, 30, 26); rect(frame, (200, 255, 215), x + 4, y - 7, 24, 20); text(frame, 'EXIT', x + 16, y - 6, (20, 70, 40), 10, 'c', False)
        else:
            rect(frame, (255, 120, 170), x + 1, y - 10, 30, 26); rect(frame, WHITE, x + 14, y - 10, 4, 26); rect(frame, WHITE, x + 1, y + 1, 30, 4)
            pygame.draw.ellipse(frame, WHITE, (x + 7, y - 17, 9, 7), 1); pygame.draw.ellipse(frame, WHITE, (x + 16, y - 17, 9, 7), 1)
    def draw_fobj(s, o, cx, cy):
        k = o['k']; x = int(o['x']) - cx; y = int(o['y']) - cy; F = s.fun
        if k == 'balloons':
            a = o['a']; rect(frame, (90, 70, 100), x - 2, y - 3, 4, 3)
            for i in range(3):
                ph = s.t * 1.4 + a * 1.7 + i * 2.1; bx = x + (-6, 0, 6)[i] + int(math.sin(ph) * 2); by = y - 30 - (i % 2) * 6 + int(math.sin(ph * 1.3) * 2); col = BAL_COLS[(a + i * 2) % 6]
                pygame.draw.line(frame, (220, 220, 230), (x, y - 3), (bx, by + 7), 1); pygame.draw.ellipse(frame, col, (bx - 5, by - 6, 10, 13)); rect(frame, mixc(col, WHITE, .6), bx - 3, by - 4, 2, 3)
            return
        img = FSPR[(k, o['a'] % 6)] if k in ('pillar', 'cabinet', 'gift', 'hidetable') else FSPR[k]
        if k in ('pillar', 'cabinet', 'gift'): frame.blit(SHD, (x - 7, y - 4))
        bx = x - img.get_width() // 2; by = y - img.get_height() + 1; frame.blit(img, (bx, by))
        if k == 'hidetable' and F['hid'] is o and int(s.t * 2) % 9 != 0:                       # two eyes glint in the dark gap under the cloth
            for ex in (bx + 16, bx + 21): rect(frame, WHITE, ex, by + 15, 2, 2); rect(frame, INK, ex + 1, by + 16, 1, 1)
        if k == 'cake' and F['cake']:
            for c in (11, 15, 19, 23): fl = int(s.t * 10 + c) % 2; rect(frame, GOLD, bx + c, by - 1 - fl, 2, 3); rect(frame, WHITE, bx + c, by - fl, 1, 1)
        elif k == 'jukebox':
            for i in range(3): rect(frame, DISCO[(int(s.t * (6 if F['music'] else 1)) + i) % 6], bx + 9 + i * 5, by + 29, 2, 2)
            if F['music']:
                for i in range(3): rect(frame, BAL_COLS[(i * 2) % 6], bx + 6 + i * 9 + int(math.sin(s.t * 3 + i) * 3), by - 4 - int((s.t * 18 + i * 9) % 20), 2, 2)
        if 'key' in o and o['key'] in F['done']:
            sx = x; sy = by - 7; poly(frame, GOLD, [(sx, sy - 4), (sx + 4, sy), (sx, sy + 4), (sx - 4, sy)]); rect(frame, WHITE, sx - 1, sy - 1, 2, 2)
    def draw_pg(s, m, cx, cy):
        x = int(m.x) - cx; y = int(m.y) - cy; mad = m.mode == 'chase'
        f = int(m.t * (6 if mad else 3)) % 2 if m.mv else 0; img = PARTYGOER[(m.kind, f, mad)]
        frame.blit(SHD, (x - 7, y - 3))
        if m.stun > 0: img = img.copy(); img.set_alpha(150)
        frame.blit(img, (x - img.get_width() // 2, y - img.get_height() + 3 + int(math.sin(m.t * 3))))
        if m.stun > 0: text(frame, '*', x, y - 54, CYAN, 14, 'c')
        elif mad: text(frame, '!', x, y - 56, RED, 14, 'c')
    def draw_fun(s):
        R = s.R; p = s.p; F = s.fun; D_ = F['D']; cx = int(s.cam); cy = int(s.camy)
        frame.blit(get_art(s.ri), (0, 0), (cx, cy, W, H))
        s.draw_fexit(cx, cy)
        items = []
        for o in D_['objs']:
            if -64 < o['x'] - cx < W + 64 and -20 < o['y'] - cy < H + 70: items.append((o['y'], 0, o))
        for m in F['pgs']:
            if -30 < m.x - cx < W + 30 and -20 < m.y - cy < H + 40: items.append((m.y, 1, m))
        items.append((p.y, 2, None)); items.sort(key=lambda a: a[0])
        for sy, k, o in items:
            if k == 0: s.draw_fobj(o, cx, cy)
            elif k == 1: s.draw_pg(o, cx, cy)
            else:
                if F['hid'] or (p.inv > 0 and int(p.inv * 14) % 2 == 0): continue
                f = int(p.anim) % 4 if p.moving else 0; x = int(p.x) - cx; y = int(p.y) - cy; lx, ly = s.lantern_pos(); lx = int(lx) - cx; ly = int(ly) - cy
                frame.blit(SHD, (x - 7, y - 3))
                frame.blit(GIRL[(p.dir, f)], (x - 9, y - 23))
        amb = R['ambient']
        if F['music']: amb = mixc(amb, (170, 150, 190), .35)
        if (math.sin(s.t * 31) + math.sin(s.t * 13 + 1)) > 1.75: amb = mixc(amb, (50, 40, 60), .45)
        apply_light(amb, s.fun_lights(cx, cy))
        frame.blit(vignette(), (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        if F['hid']: frame.fill((170, 170, 184), special_flags=pygame.BLEND_RGB_MULT)
        if s.pulse_t > 0:
            r = int(70 * (1 - s.pulse_t / .4)); pygame.draw.ellipse(frame, (255, 244, 200), (int(p.x) - cx - r, int(p.y) - cy - 8 - int(r * .6), 2 * r + 1, int(r * 1.2) + 1), 1)
        for q in s.parts: rect(frame, q[5], q[0] - cx, q[1] - cy, 2, 2)
        t = s.fun_near() if (not s.dlg and s.state == 'play' and not F['hid']) else None
        if t:
            x = t[1] - cx; y = t[2] - cy - (30 if t[0] == 'note' else 42) + int(math.sin(s.t * 6) * 2)
            box((x - 7, y - 8, 14, 14), (20, 22, 36), GOLD); text(frame, '!', x, y - 7, GOLD, 14, 'c', False)
        if F['hid']: text(frame, 'HIDDEN. PRESS ACT TO COME OUT.', W // 2, 158, (255, 236, 190), 11, 'c')
        rect(frame, (8, 6, 16), 256, 18, FGW + 4, FGH + 4); frame.blit(F['mm'], (258, 20))
        if int(s.t * 3) % 2 == 0: rect(frame, GOLD, 258 + int(p.x // FTS) - 1, 20 + int(p.y // FTS) - 1, 3, 3)
        s.draw_hud()
    # ---------------- the opening: Mira's home, the night her parents fight
    HOME_T1 = [('FATHER', 'Where the hell have you been all this time?!'), ('MOTHER', 'It is none of your business.'),
               ('MOTHER', 'Oh, Mira! What are you doing here? Go back to bed, so that someone named Dean can come and leave a present under your bed.'), ('MIRA', 'Really? Then I am going.')]
    HOME_T2 = [('FATHER', 'I will not let a slut into my house. Now get out.'), ('MOTHER', 'Shut up! This is MY house.'),
               ('MOTHER', 'While you were out getting drunk and never coming home, I was working and paying for everything.'),
               ('MOTHER', 'I bought this house. I am leaving now.'), ('MOTHER', 'And when I come back in the morning, Mira and I are leaving here.')]
    def home_init(s):
        p = s.p; p.x = 90.0; p.y = 150.0; p.dir = 'r'; p.moving = False; s.cam = 0.0; s.camy = 0.0
        s.hm = {'ph': 'sleep', 't': 0.0, 'sh': .5, 'mx': 272.0, 'gone': False}; s.dlg = []; s.msg_t = 0.0; s.banner_t = 0.0
    def home_after1(s): s.hm['ph'] = 'toBed'; s.hm['t'] = 0.0
    def home_after2(s): s.hm['ph'] = 'leave'; s.hm['t'] = 0.0
    def home_done(s): s.begin_comic(INTRO, lambda: s.start_room(0, True))
    def up_home(s, dt, ev):
        p = s.p; h = s.hm; ph = h['ph']; h['t'] += dt
        for e in ev:
            if e[0] == 'key' and e[1] == 'back': s.pause_to = 'play'; s.state = 'pause'; return
            if e[0] == 'tap' and e[1] > 296 and e[2] < 20: s.pause_to = 'play'; s.state = 'pause'; return
        if ph in ('sleep', 'wake', 'walk'):                                  # muffled shouting through the wall
            h['sh'] -= dt
            if h['sh'] <= 0: h['sh'] = random.uniform(.25, .6); s.sfx(random.choice(('blip_c', 'blip_v', 'blip_c')), .25)
        if ph == 'sleep':
            if h['t'] > 3.2: h['ph'] = 'wake'; h['t'] = 0.0; s.sfx('thump', .5); s.say('SHOUTING FROM THE HALL...', 3.2)
        elif ph == 'wake':
            if h['t'] > 1.6: h['ph'] = 'walk'; h['t'] = 0.0
        elif ph == 'walk':
            mx, my = s.mv; p.moving = math.hypot(mx, my) > .1
            nx = clamp(p.x + mx * SPEED * .9 * dt, 88, 250); ny = clamp(p.y + my * SPEED * .8 * dt, FY0 + 6, FY1)
            p.x = nx; p.y = ny
            if p.moving:
                if abs(mx) >= abs(my) * .9: p.dir = 'r' if mx > 0 else 'l'
                else: p.dir = 'u' if my < 0 else 'd'
                p.anim += dt * 8; p.stepT -= dt
                if p.stepT <= 0: p.stepT = .3; s.sfx('step', .35)
            else: p.anim = 0.0
            if p.x > 196: p.moving = False; p.anim = 0.0; p.dir = 'r'; h['ph'] = 'talk1'; s.talk(s.HOME_T1, s.home_after1)
        elif ph == 'toBed':
            p.moving = True; p.dir = 'l'; p.anim += dt * 8; p.x -= 58 * dt; p.y += (150 - p.y) * min(1.0, dt * 4)
            if int(p.anim) % 4 == 0 and p.stepT <= 0: s.sfx('step', .3)
            p.stepT -= dt
            if p.stepT <= 0: p.stepT = .3
            if p.x <= 90: p.x = 90.0; p.moving = False; h['ph'] = 'lie'; h['t'] = 0.0; s.sfx('creak', .4)
        elif ph == 'lie':
            if h['t'] > 1.2: h['ph'] = 'talk2'; s.talk(s.HOME_T2, s.home_after2)
        elif ph == 'leave':
            if not h['gone']:
                h['mx'] += 80 * dt
                if h['mx'] >= 296: h['gone'] = True; s.sfx('thump'); s.shake = .4; h['t'] = 0.0
            elif h['t'] > 1.6: h['ph'] = 'end'; s.fade_to(s.home_done)
    def draw_home(s):
        p = s.p; h = s.hm; ph = h['ph']
        rect(frame, (88, 66, 84), 0, 0, W, 108); rect(frame, (102, 78, 96), 156, 0, 164, 108)
        for x in range(8, 156, 16): rect(frame, (82, 60, 78), x, 0, 2, 108)
        for x in range(164, W, 16): rect(frame, (94, 72, 90), x, 0, 2, 108)
        rect(frame, (60, 38, 34), 0, 104, W, 6); rect(frame, (112, 76, 52), 0, 110, W, H - 110)
        for y in range(116, H, 12): rect(frame, (98, 64, 44), 0, y, W, 1)
        for x in range(0, W, 28): rect(frame, (98, 64, 44), x, 110, 1, H - 110)
        rect(frame, (48, 36, 40), 78, 22, 42, 50); rect(frame, (16, 22, 56), 81, 25, 36, 44); rect(frame, (48, 36, 40), 98, 25, 2, 44); rect(frame, (48, 36, 40), 81, 46, 36, 2)
        pygame.draw.circle(frame, (232, 236, 246), (108, 36), 5)
        rect(frame, (56, 36, 34), 148, 20, 8, 88); rect(frame, (30, 22, 32), 150, 28, 4, 80)                       # the bedroom doorway
        for fx, fy in ((176, 34), (196, 40), (216, 32)): rect(frame, (60, 42, 36), fx, fy, 14, 18); rect(frame, (196, 176, 150), fx + 2, fy + 2, 10, 14)   # family photos
        rect(frame, (70, 44, 34), 284, 34, 34, 74); rect(frame, (98, 64, 46), 288, 38, 26, 66); rect(frame, GOLD, 308, 76, 3, 3)       # the front door
        rect(frame, (120, 60, 70), 266, 168, 44, 8)
        rect(frame, (50, 40, 44), 235, 0, 2, 22); poly(frame, (230, 196, 120), [(226, 30), (246, 30), (240, 20), (232, 20)])             # hall lamp
        rect(frame, (86, 56, 40), 6, 116, 6, 36); rect(frame, (96, 64, 44), 6, 140, 74, 10); rect(frame, (96, 64, 44), 8, 150, 4, 6); rect(frame, (96, 64, 44), 74, 150, 4, 6)
        rect(frame, (232, 228, 244), 12, 132, 64, 8); rect(frame, (250, 250, 255), 13, 126, 18, 7)
        if ph in ('sleep', 'lie', 'talk2'):                                      # Mira lies in bed
            pygame.draw.circle(frame, (238, 196, 160), (24, 128), 5); rect(frame, (96, 60, 44), 18, 122, 12, 4); rect(frame, (92, 122, 184), 28, 128, 46, 12); rect(frame, (72, 100, 160), 28, 134, 46, 2)
            if ph == 'sleep':
                for k in range(3): text(frame, 'z', 36 + k * 8, 112 - k * 8 - int((s.t * 6 + k * 3) % 6), (220, 224, 255), 12, 'c', False)
        elif ph == 'wake':                                                       # sits up, startled
            pygame.draw.circle(frame, (238, 196, 160), (28, 118), 5); rect(frame, (96, 60, 44), 22, 112, 12, 4); rect(frame, (240, 236, 220), 24, 122, 10, 12)
            rect(frame, (92, 122, 184), 30, 132, 44, 8)
            text(frame, '!', 28, 96, (255, 230, 120), 16, 'c', False)
        else: rect(frame, (92, 122, 184), 34, 132, 38, 7)
        items = [(150.0, 'dad'), (148.0, 'mom')]
        if ph in ('walk', 'talk1', 'toBed'): items.append((p.y, 'mira'))
        items.sort(key=lambda a: a[0])
        arguing = ph in ('sleep', 'wake', 'walk', 'talk1', 'talk2')
        for sy, k in items:
            if k == 'dad':
                im, dy = person_img(0, s.t, 1, 0.0, 'argue' if arguing else 'still'); frame.blit(SHD, (236 - 7, 147)); frame.blit(im, (236 - 11, 150 - 34 + 3 + dy))
            elif k == 'mom' and not h['gone']:
                mx = int(h['mx']); im, dy = person_img(1, s.t, 1, 0.0, 'walk') if ph == 'leave' else person_img(1, s.t, -1, _ARGUE_T / 2, 'argue' if arguing else 'still')
                frame.blit(SHD, (mx - 7, 145)); frame.blit(im, (mx - 11, 148 - 34 + 3 + dy))
            elif k == 'mira':
                f = int(p.anim) % 4 if p.moving else 0; x = int(p.x); y = int(p.y); frame.blit(SHD, (x - 7, y - 3)); frame.blit(GIRL[(p.dir, f)], (x - 9, y - 23))
        amb = (30, 26, 44) if ph == 'sleep' else (74, 64, 90)
        apply_light(amb, [(240, 70, 110, (255, 214, 150)), (108, 50, 54, (110, 130, 210)), (60, 120, 40, (150, 120, 100))])
        frame.blit(vignette(), (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        s.draw_hud()
    # ================================================================ TOP-DOWN LEVELS (the house, the temple, the forest ... every level except Level Fun)
    def td_start(s, i, intro=True):
        R = s.R = ROOMS[i]; s.ri = i; M = td_map(R['td'])
        if R['goal'] == 'dean' and not R.get('final'): s.save.pop('dl', None)
        if i >= 3 and i != HOME_I: s.has_heart = True
        s.p = Player(M.spawn[0] * TS + 8, M.spawn[1] * TS + 8); s.p.dir = 'd'; s.p.maxhp = (4 if s.has_heart else 3) - (1 if s.save.get('dl') else 0); s.p.hp = s.p.maxhp
        s.mons = []; s.stones = []; s.candles = []; s.obst = []; s.boss = None; s.dean = None; s.halls = None; s.fun = None; s.parts = []; s.pulse_t = 0.0; s.won_t = 0.0; s.msg_t = 0.0
        s.dlg = []; s.choice = None; s.hb_t = 0.0; s.scare_t = 0.0; s.strike_t = 0.0; s.dead_to = None; s.pause_to = 'play'; s.trial_hard = bool(R.get('final')); s.next_stone = 0; s.item_t = 0.0
