        s.p = Player(T['ckpt'][0], T['ckpt'][1]); s.p.maxhp = hp; s.p.hp = hp; s.p.inv = 2.0
        T['mons'] = [m for m in (TMon(*q) for q in M.mons if q[0] != 'doll')]; T['flow'] = None; s.state = 'play'; s.fade = 1.0; s.fade_dir = -1; s.fade_act = None; s.dead_to = None; s.parts = []
