    def draw_hud(s):
        p = s.p
        home = s.R.get('house'); nolant = home or s.R.get('nolantern')
        if not home:
            for i in range(p.maxhp): frame.blit(HEART if i < p.hp else HEART_DIM, (4 + i * 11, 4))
            if s.has_heart: frame.blit(HEARTITEM, (60, 11))
        if not nolant:
            frame.blit(LANT, (4, 14)); rect(frame, GREYT, 13, 16, 42, 6); rect(frame, (20, 20, 30), 14, 17, 40, 4)
            rect(frame, GOLD if p.energy >= 30 else (150, 110, 80), 14, 17, int(p.energy * .4), 4)
        rect(frame, GREYT, 302, 4, 3, 10); rect(frame, GREYT, 308, 4, 3, 10)
