        gx = 160; gy = 148; fl = int(math.sin(t * 9) * 2)
        frame.blit(SHD, (gx - 7, gy - 3)); frame.blit(GIRL[('d', 0)], (gx - 9, gy - 23)); frame.blit(LANT, (gx + 5, gy - 14))
        frame.blit(light(46 + fl, (255, 200, 120)), (gx + 8 - 46 - fl, gy - 10 - 46 - fl), special_flags=pygame.BLEND_RGB_ADD)
        for q in s.snow: q[1] += 0; rect(frame, WHITE, q[0], q[1], 1, 1)
        for i, (x0, y0) in enumerate(((42, 112), (60, 118), (240, 108))): rect(frame, (255, 190, 110), x0 + int(math.sin(t * 2 + i) * 6), y0 - int((t * 6 + i * 9) % 30), 1, 1)   # drifting embers
